NAME = 'FinSTLK2017: Pyhä Raamattu (STLK 2017)'
BOOK = 'II Samuel'

CHAPTERS = {
    1: {
        1: 'Tapahtui Saulin kuoleman jälkeen, että Daavid voitettuaan amalekilaiset oli palannut takaisin ja ollut Siklagissa pari päivää,',
        2: 'kolmantena päivänä tuli eräs mies leiristä Saulin luota vaatteet reväistyinä ja multaa pään päällä. Kun hän tuli Daavidin luo, hän lankesi ja kumartui maahan.',
        3: 'Daavid kysyi häneltä: "Mistä tulet?" Hän vastasi hänelle: "Minä olen päässyt pakoon Israelin leiristä."',
        4: 'Daavid sanoi hänelle: "Miten asiat ovat? Kerro minulle." Hän vastasi: "Väki on paennut taistelusta, paljon väkeä on kaatunut ja kuollut, myös Saul ja hänen poikansa Joonatan ovat kuolleet."',
        5: 'Daavid kysyi nuorelta mieheltä, joka kertoi tämän hänelle: "Mistä tiedät, että Saul ja hänen poikansa Joonatan ovat kuolleet?"',
        6: 'Nuorukainen, joka oli kertonut hänelle tämän, vastasi: "Minä tulin sattumalta Gilboan vuorelle, ja katso, Saul nojasi keihääseensä, ja sotavaunut ja ratsumiehet ahdistivat häntä.',
        7: "Hän kääntyi taakseen ja nähdessään minut hän huusi minua. Vastasin: 'Tässä olen.'",
        8: "Niin hän kysyi minulta: 'Kuka olet?' Vastasin hänelle: 'Olen amalekilainen.'",
        9: "Sitten hän sanoi minulle: 'Asetu vierelleni seisomaan ja surmaa minut, sillä minä olen kangistumassa, vaikka olenkin vielä täysin hengissä.'",
        10: 'Niin astuin hänen luokseen ja surmasin hänet, sillä käsitin, ettei hän kaatumisensa jälkeen jäisi henkiin. Sitten otin kruunun, joka oli hänen päässään, ja rannerenkaan, joka oli hänen käsivarressaan, ja toin ne tänne herralleni."',
        11: 'Daavid tarttui vaatteisiinsa ja repäisi ne, samoin tekivät kaikki miehet, jotka olivat hänen kanssaan.',
        12: 'He pitivät valittajaisia ja itkivät ja paastosivat iltaan asti Saulin ja hänen poikansa Joonatanin tähden ja Herran kansan tähden ja Israelin heimon tähden, koska he olivat kaatuneet miekkaan.',
        13: 'Daavid kysyi nuorukaiselta, joka oli hänelle kertonut tämän: "Mistä sinä olet?" Hän vastasi: "Minä olen muukalaisen, amalekilaisen miehen poika."',
        14: 'Daavid sanoi hänelle: "Kuinka et pelännyt ojentaa kättäsi tuhotaksesi Herran voidellun?"',
        15: 'Daavid kutsui yhden palvelijoistaan ja sanoi: "Käy tänne, lyö hänet kuoliaaksi." Ja hän iski hänet kuoliaaksi.',
        16: 'Mutta Daavid sanoi hänelle: "Sinun veresi tulkoon oman pääsi päälle, sillä oma suusi on todistanut sinua vastaan, kun sanoit: \'Minä olen surmannut Herran voidellun.\'"',
        17: 'Daavid viritti tämän itkuvirren Saulista ja hänen pojastaan Joonatanista',
        18: 'ja käski opettaa sen, "Jousilaulun", Juudan pojille: katso, se on kirjoitettuna "Oikeamielisen kirjassa":',
        19: '"Kaunistuksesi, Israel, on surmattuna kukkuloillasi. Kuinka ovatkaan sankarit kaatuneet!',
        20: 'Älkää ilmoittako sitä Gatissa, älkää julistako voitonsanomaa Askelonin kaduilla, etteivät filistealaisten tyttäret iloitsisi, etteivät ympärileikkaamattomien tyttäret riemuitsisi.',
        21: 'Te Gilboan vuoret, älköön teille kastetta tulko, älköön sadetta, älköön peltoja, joista anteja uhrataan. Sillä sinne on heitetty pois sankarien kilpi, Saulin kilpi, öljyllä voitelemattomana.',
        22: 'Kaatuneitten verta, sankarien rasvaa Joonatanin jousi ei väistänyt, eikä palannut tyhjänä Saulin miekka.',
        23: 'Saul ja Joonatan, rakkaat ja armaat, olivat elämässä ja kuolemassa erottamattomat, olivat nopeammat kuin kotkat, leijonia väkevämmät.',
        24: 'Te Israelin tyttäret, itkekää Saulia, häntä, joka puetti teidät purppuraan ja koruihin, joka kiinnitti pukuunne kultakoristeita.',
        25: 'Kuinka ovat sankarit taistelussa kaatuneet! Joonatan on surmattuna kukkuloillasi.',
        26: 'Minä suren sinua, veljeni Joonatan. Sinä olit minulle hyvin rakas. Rakkautesi oli minulle ihmeellisempi kuin naisen rakkaus.',
        27: 'Kuinka ovatkaan sankarit kaatuneet, kuinka ovat hukkuneet taisteluaseet!"',
    },
    2: {
        1: 'Sen jälkeen tapahtui, että Daavid kysyi Herralta: "Menenkö ylös johonkin Juudan kaupunkiin?" Herra vastasi hänelle: "Mene." Vielä Daavid kysyi: "Mihin [kaupunkiin] menen?" Hän vastasi: "Hebroniin."',
        2: 'Daavid meni sinne mukanaan molemmat vaimonsa, jisreeliläinen Ahinoam ja Abigail, karmelilaisen Naabalin [leski] vaimo.',
        3: 'Daavid vei sinne myös miehet, jotka olivat hänen kanssaan, kunkin perheineen, ja he asettuivat Hebronin ympärillä oleviin kaupunkeihin.',
        4: 'Sitten Juudan miehet tulivat ja voitelivat siellä Daavidin Juudan heimon kuninkaaksi. Kun Daavidille ilmoitettiin, että Gileadin Jaabeksen miehet olivat haudanneet Saulin,',
        5: 'Daavid lähetti lähettiläät Gileadin Jaabeksen miesten luo sanomaan heille: " Herra siunatkoon teitä, koska olette osoittaneet herrallenne Saulille laupeutta hautaamalla hänet.',
        6: 'Osoittakoon Herra nyt laupeutta ja uskollisuutta teitä kohtaan. Minäkin teen teille hyvää, koska tämän teitte.',
        7: 'Rohkaiskaa siis itsenne ja olkaa urhoolliset. Tosin teidän herranne Saul on kuollut, mutta Juudan heimo on voidellut minut kuninkaakseen."',
        8: 'Mutta Abner, Neerin poika, Saulin sotapäällikkö, otti Saulin pojan Iisbosetin ja vei hänet Mahanaimiin',
        9: 'ja asetti hänet Gileadin, Asurin, Jisreelin, Efraimin, Benjaminin ja koko Israelin kuninkaaksi.',
        10: 'Saulin poika Iisboset oli neljänkymmenen vuoden vanha tullessaan Israelin kuninkaaksi ja hallitsi kaksi vuotta. Ainoastaan Juudan heimo seurasi Daavidia.',
        11: 'Aika, minkä Daavid oli Juudan heimon kuninkaana Hebronissa, oli seitsemän vuotta ja kuusi kuukautta.',
        12: 'Abner, Neerin poika, ja Saulin pojan Iisbosetin palvelijat lähtivät Mahanaimista Gibeoniin.',
        13: 'Jooab, Serujan poika, ja Daavidin palvelijat lähtivät hekin liikkeelle ja kohtasivat toisensa Gibeonin lammikolla. He asettuivat toiset tälle, toiset tuolle puolelle lammikkoa.',
        14: 'Silloin Abner sanoi Jooabille: "Nouskoon nuoria miehiä pitämään taistelukisaa edessämme." Jooab sanoi: "Nouskoon vain."',
        15: 'Heitä nousi ja astui esiin sama määrä: kaksitoista Benjaminin ja Saulin pojan Iisbosetin puolelta sekä kaksitoista Daavidin palvelijaa.',
        16: 'He tarttuivat kukin vastustajaansa päästä ja pistivät miekkansa toinen toisensa kylkeen ja kaatuivat yhdessä. Niin sen paikan nimeksi tuli Helkat-Suurim. Se on Gibeonin luona.',
        17: 'Sinä päivänä syntyi erittäin kova taistelu, mutta Daavidin palvelijat voittivat Abnerin ja Israelin miehet.',
        18: 'Siellä oli kolme Serujan poikaa: Jooab, Abisai ja Asael. Mutta Asael oli nopeajalkainen kuin gaselli kedolla.',
        19: 'Asael ajoi takaa Abneria eikä poikennut oikealle eikä vasemmalle Abnerin jäljestä.',
        20: 'Abner kääntyi taakseen ja sanoi: "Sinäkö se olet, Asael?" Hän vastasi: "Minä."',
        21: 'Abner sanoi hänelle: "Käänny oikealle tai vasemmalle ja ota joku noista nuorukaisista kiinni ja riistä häneltä sota-asu." Mutta Asael ei tahtonut luopua hänestä.',
        22: 'Abner vielä kerran sanoi Asaelille: "Luovu minusta, muuten lyön sinut maahan. Mutta kuinka sitten voisin katsoa veljeäsi Jooabia silmiin?"',
        23: 'Mutta kun hän ei tahtonut luopua hänestä, Abner pisti häntä keihään varsipuolella vatsaan, niin että keihäs tuli takaa ulos. Niin hän kaatui ja kuoli siihen paikkaan. Jokainen, joka tuli siihen paikkaan, mihin Asael oli kaatunut ja kuollut, pysähtyi siihen.',
        24: 'Mutta Jooab ja Abisai ajoivat Abneria takaa ja tulivat, kun aurinko oli laskenut, Amman kukkulalle, joka on vastapäätä Giiahia, Gibeonin erämaahan päin.',
        25: 'Benjaminilaiset kokoontuivat Abnerin taakse yhteen joukkoon ja asettuivat kukkulan laelle.',
        26: 'Abner huusi Jooabille ja sanoi: "Pitääkö miekan syödä ikuisesti? Etkö ymmärrä, että siitä tulee vain katkeruutta perästäpäin? Etkö jo käske väen lakata ajamasta takaa veljiään?"',
        27: 'Jooab vastasi: "Niin totta kuin Jumala elää: jos et olisi puhunut, varmasti väki olisi vasta huomenaamulla lähtenyt pois ajamasta takaa veljiään."',
        28: 'Jooab puhalsi torveen, ja kaikki väki pysähtyi eikä enää ajanut takaa Israelia, eivätkä he enää taistelleet.',
        29: 'Abner ja hänen miehensä kulkivat koko sen yön Aromaata ja menivät Jordanin yli, vaelsivat koko Bitronin läpi ja tulivat Mahanaimiin.',
        30: 'Jooab kokosi kaiken kansan palattuaan ajamasta takaa Abneria. Daavidin palvelijoista puuttui yhdeksäntoista miestä ja Asael.',
        31: 'Daavidin palvelijat olivat lyöneet benjaminilaisia ja Abnerin miehiä kuoliaaksi kolmesataa kuusikymmentä miestä.',
        32: 'He ottivat Asaelin ja hautasivat hänet hänen isänsä hautaan Beetlehemiin. Jooab ja hänen miehensä kulkivat koko sen yön ja tulivat päivän valjetessa Hebroniin.',
    },
    3: {
        1: 'Sota Saulin suvun ja Daavidin suvun välillä pitkittyi. Daavid vahvistui vahvistumistaan, mutta Saulin suku heikkeni heikkenemistään.',
        2: 'Daavidille syntyi poikia Hebronissa. Hänen esikoisensa oli Amnon, jonka äiti oli jisreeliläinen Ahinoam.',
        3: 'Hänen toinen poikansa oli Kilab, jonka äiti oli Abigail, karmelilaisen Naabalin [leski] vaimo. Kolmas oli Absalom, Gesurin kuninkaan Talmain tyttären, Maakan, poika.',
        4: 'Neljäs oli Adonia, Haggitin poika, ja viides Sefatja, Abitalin poika.',
        5: 'Kuudes oli Jitream, Daavidin vaimon Eglan poika. Nämä syntyivät Daavidille Hebronissa.',
        6: 'Niin kauan kuin sota oli Saulin suvun ja Daavidin suvun välillä, piti Abner voimakkaasti Saulin suvun puolta.',
        7: 'Saulilla oli ollut sivuvaimo, nimeltä Rispa, Aijan tytär. Iisboset sanoi Abnerille: "Miksi olet mennyt isäni sivuvaimon luo?"',
        8: 'Abner vihastui kovin Iisbosetin sanoista ja sanoi: "Olenko minä koiranpää, Juudasta kotoisin? Kun nytkin osoitan laupeutta isäsi Saulin suvulle, hänen veljilleen ja ystävilleen enkä ole antanut sinun joutua Daavidin käsiin, niin kuitenkin nyt syytät minua rikoksen teosta naiselle.',
        9: 'Jumala rangaiskoon Abneria nyt ja vasta, jos en tee Daavidille, niin kuin Herra on hänelle vannonut:',
        10: 'otan pois kuninkuuden Saulin suvulta ja pystytän Daavidille valtaistuimen Israeliin ja Juudaan, Daanista aina Beersebaan asti."',
        11: 'Hän ei voinut enää vastata Abnerille sanaakaan, sillä hän pelkäsi häntä.',
        12: 'Mutta Abner lähetti sanansaattajia Daavidin luo sanomaan: "Kenen on maa?" ja vielä näin: "Tee liitto kanssani. Katso, käteni on oleva kanssasi ja kääntävä koko Israelin puolellesi."',
        13: 'Hän vastasi: "Hyvä, minä teen liiton kanssasi. Yhtä minä kuitenkin vaadin sinulta: älä astu kasvojeni eteen tuomatta Miikalia, Saulin tytärtä, kun tulet astuaksesi kasvojeni eteen."',
        14: 'Sitten Daavid lähetti sanansaattajat Iisbosetin, Saulin pojan, luo sanomaan: "Anna minulle vaimoni Miikal, jonka olen kihlannut itselleni sadalla filistealaisten esinahalla."',
        15: 'Iisboset lähetti ottamaan hänet hänen mieheltään Paltielilta, Laiksen pojalta.',
        16: 'Hänen miehensä lähti hänen mukanaan ja seurasi häntä aina Bahurimiin asti itkien lakkaamatta. Abner sanoi hänelle: "Mene tiehesi, palaa takaisin." Hän palasi takaisin.',
        17: 'Abner oli neuvotellut Israelin vanhinten kanssa sanoen: "Jo kauan olette halunneet saada Daavidin kuninkaaksenne.',
        18: 'Pankaa se nyt toimeen, sillä Herra on sanonut Daavidille näin: \'Palvelijani Daavidin kädellä vapautan kansani Israelin filistealaisten käsistä ja kaikkien heidän vihollistensa käsistä.\'"',
        19: 'Abner puhui tämän myös benjaminilaisille, ja Abner meni ja puhui Daavidillekin Hebronissa, mitä mieltä Israel ja koko Benjaminin heimo olivat.',
        20: 'Kun Abner tuli Daavidin luo Hebroniin, mukanaan kaksikymmentä miestä, Daavid laittoi pidot Abnerille ja miehille, jotka olivat hänen kanssaan.',
        21: 'Abner sanoi Daavidille: "Nousen ja menen kokoamaan kaiken Israelin herrani, kuninkaan, luo, että he tekisivät liiton kanssasi ja saisit hallittaviksesi kaikki, joita haluat." Daavid päästi Abnerin menemään, ja hän lähti rauhassa.',
        22: 'Katso, Daavidin palvelijat ja Jooab tulivat ryöstöretkeltä ja toivat mukanaan paljon saalista. Mutta Abner ei ollut enää Daavidin luona Hebronissa, sillä tämä oli päästänyt hänet menemään, ja hän oli lähtenyt rauhassa.',
        23: 'Kun Jooab ja kaikki sotaväki, joka oli hänen kanssaan, tulivat, kerrottiin Jooabille: "Abner, Neerin poika, tuli kuninkaan luo, ja hän päästi hänet menemään, ja hän lähti rauhassa."',
        24: 'Silloin Jooab meni kuninkaan luo ja sanoi: "Mitä olet tehnyt? Katso, Abner tuli luoksesi, miksi päästit hänet menemään menojaan?',
        25: 'Etkö ymmärrä, että Abner, Neerin poika, tuli pettämään sinua ja urkkimaan lähtöäsi ja tuloasi ja kaikkea, mitä teet?"',
        26: 'Jooab lähti Daavidin luota ja lähetti sanansaattajat Abnerin jälkeen, ja he palauttivat hänet takaisin Boor-Siirasta, eikä Daavid tiennyt siitä mitään.',
        27: 'Kun Abner tuli takaisin Hebroniin, Jooab vei hänet syrjään porttiholvin keskelle muka puhutellakseen häntä kahden kesken, ja pisti häntä siellä vatsaan, niin että hän kuoli Jooabin veljen Asaelin veren tähden.',
        28: 'Kun Daavid sitten sai sen kuulla, hän sanoi: "Abnerin, Neerin pojan, vereen minä olen viaton ja myös kuninkuuteni Herran edessä iankaikkisesti.',
        29: 'Tulkoon se Jooabin pään päälle ja kaiken hänen isänsä perheen päälle, älköötkä Jooabin suvusta loppuko vuotoa tai spitaalia sairastavat, kainalosauvoilla kulkijat, miekkaan kaatuvat ja leivän puutteessa olijat."',
        30: 'Näin Jooab ja hänen veljensä Abisai tappoivat Abnerin, sen tähden että tämä oli surmannut heidän veljensä Asaelin taistelussa Gibeonin luona.',
        31: 'Mutta Daavid sanoi Jooabille ja kaikelle väelle, joka oli hänen kanssaan: "Reväiskää vaatteenne ja kääriytykää säkkeihin ja pitäkää valittajaiset Abnerille." Kuningas Daavid kulki paarien perässä.',
        32: 'He hautasivat Abnerin Hebroniin, ja kuningas korotti äänensä ja itki Abnerin haudalla, ja kaikki kansa itki.',
        33: 'Kuningas viritti itkuvirren Abnerista ja sanoi: "Pitikö Abnerin kuolla, niin kuin houkka kuolee?',
        34: 'Eivät olleet kätesi sidotut eivätkä jalkasi vaskikahleisiin pannut. Sinä kaaduit, kuin kaadutaan vilpillisten käden kautta." Kaikki kansa itki häntä vielä enemmän.',
        35: 'Sitten kaikki kansa tuli, kun vielä oli päivä, vaatimaan, että Daavid söisi jotakin. Mutta Daavid vannoi sanoen: "Jumala rangaiskoon minua nyt ja vasta, jos maistan leipää tai muuta, ennen kuin aurinko laskee."',
        36: 'Kun kaikki kansa sai kuulla sen, se miellytti heitä, samoin kuin kaikelle kansalle oli mieleen kaikki muukin, mitä kuningas teki.',
        37: 'Kaikki kansa ja koko Israel ymmärsivät sinä päivänä, että Abnerin, Neerin pojan, surma ei ollut lähtenyt kuninkaasta.',
        38: 'Kuningas sanoi palvelijoilleen: "Ettekö tiedä, että ruhtinas ja suuri mies on tänä päivänä kaatunut Israelissa?',
        39: 'Minä olen kuitenkin vielä heikko, vaikka minut on voideltu kuninkaaksi, mutta nuo miehet, Serujan pojat, ovat liian väkivaltaisia minun hillitä. Herra maksakoon sille, joka tekee pahaa, hänen pahuutensa mukaan."',
    },
    4: {
        1: 'Kun Saulin poika kuuli Abnerin kuolleen Hebronissa, hänen kätensä herposivat, ja koko Israel pelästyi.',
        2: 'Saulin pojalla oli partiojoukkojen päämiehinä kaksi miestä, toisen nimi oli Baana ja toisen Reekab, beerotilaisen Rimmonin poikia, benjaminilaisia, sillä Beerotkin luetaan kuuluvaksi Benjaminiin.',
        3: 'Mutta beerotilaiset olivat paenneet Gittaimiin ja asuivat siellä muukalaisina, niin kuin he asuvat vielä tänäkin päivänä.',
        4: 'Joonatanilla, Saulin pojalla, oli poika, joka oli rampa jaloistaan. Hän oli viiden vuoden vanha, kun sanoma Saulista ja Joonatanista tuli Jisreelistä. Hänen hoitajansa otti hänet mukaansa ja pakeni. Mutta kun tämä hätääntyneenä pakeni, poika putosi ja tuli ontuvaksi, ja hänen nimensä oli Mefiboset.',
        5: 'Beerotilaisen Rimmonin pojat Reekab ja Baana lähtivät matkaan ja tulivat päivän ollessa palavimmillaan Iisbosetin taloon, kun hän oli päivälevolla.',
        6: 'Katso, he tulivat silloin sisälle taloon muka ottamaan vehnänjyviä, mutta pistivät häntä vatsaan. Mutta Reekab ja hänen veljensä Baana pääsivät pakoon.',
        7: 'He tulivat taloon, kun hän lepäsi vuoteellaan makuuhuoneessaan, pistivät hänet kuoliaaksi, löivät häneltä pään poikki ja ottivat sen mukaansa. He kulkivat sitten Aromaan tietä koko yön,',
        8: 'toivat Iisbosetin pään Daavidille Hebroniin ja sanoivat kuninkaalle: "Katso, tässä on Iisbosetin, Saulin pojan, sinun vihamiehesi, pää, hänen, joka väijyi henkeäsi. Herra on tänä päivänä kostanut Saulille ja hänen jälkeläisilleen herrani, kuninkaan, puolesta."',
        9: 'Niin Daavid vastasi Reekabille ja hänen veljelleen Baanalle, beerotilaisen Rimmonin pojille, ja sanoi heille: "Niin totta kuin Herra elää, joka on vapahtanut minut kaikesta hädästä:',
        10: "Se, joka ilmoitti minulle ja sanoi: 'Katso, Saul on kuollut', luuli tuovansa ilosanoman. Mutta minä otatin hänet kiinni ja surmautin Siklagissa antaakseni hänelle sanantuojan palkan.",
        11: 'Eikö minun nyt paljoa suuremmassa määrin, kun jumalattomat miehet ovat murhanneet syyttömän miehen hänen omassa kodissaan hänen vuoteeseensa, ole vaadittava hänen verensä kädestänne ja hävitettävä teidät maan päältä?"',
        12: 'Daavid käski nuorukaisten surmata heidät. He hakkasivat poikki heidän kätensä ja jalkansa ja hirttivät heidät Hebronin lammikon rannalle. Mutta Iisbosetin pään he ottivat ja hautasivat sen Abnerin hautaan Hebroniin.',
    },
    5: {
        1: 'Kaikki Israelin sukukunnat tulivat Daavidin luo Hebroniin ja sanoivat näin: "Katso, me olemme sinun luutasi ja lihaasi.',
        2: 'Jo aikaisemmin Saulin vielä ollessa kuninkaanamme sinä saatoit Israelin lähtemään ja tulemaan. Sinulle Herra on sanonut: \'Sinä olet kaitseva kansaani Israelia, ja sinä olet oleva Israelin ruhtinas.\'"',
        3: 'Kaikki Israelin vanhimmat olivat tulleet kuninkaan luo Hebroniin, ja kuningas Daavid teki heidän kanssaan liiton Hebronissa Herran edessä. He voitelivat Daavidin Israelin kuninkaaksi.',
        4: 'Daavid oli kolmenkymmenen vuoden vanha tullessaan kuninkaaksi ja hallitsi neljäkymmentä vuotta.',
        5: 'Hebronissa hän hallitsi Juudaa seitsemän vuotta ja kuusi kuukautta, ja Jerusalemissa hän hallitsi koko Israelia ja Juudaa kolmekymmentä kolme vuotta.',
        6: 'Kuningas meni miehineen Jerusalemiin jebusilaisia vastaan, jotka asuivat siinä maassa. He sanoivat Daavidille näin: "Tänne sinä et tule, vaan sokeat ja ontuvat karkottavat sinut sanomalla: \'Ei tule Daavid tänne.\'"',
        7: 'Mutta Daavid valloitti Siionin Vuorilinnan, se on Daavidin kaupungin.',
        8: 'Daavid sanoi sinä päivänä: "Jokainen, joka surmaa jebusilaisen ja tunkeutuu vesijohdolle asti, voittaa ne sokeat ja ontuvat, joita Daavid vihaa." Sen tähden on tapana sanoa: "Sokea ja ontuva älköön tulko taloon."',
        9: 'Daavid asettui Vuorilinnaan ja kutsui sen Daavidin kaupungiksi. Daavid rakensi Millon ympäristössä ja talonsa sisällä.',
        10: 'Daavid tuli yhä mahtavammaksi, ja Herra, Jumala Sebaot, oli hänen kanssaan.',
        11: 'Hiiram, Tyyron kuningas, lähetti sanansaattajat Daavidin luo sekä setripuita, puuseppiä ja kivenhakkaajia, ja nämä rakensivat Daavidille palatsin.',
        12: 'Daavid ymmärsi, että Herra oli vahvistanut hänet Israelin kuninkaaksi ja korottanut hänen kuninkuutensa kansansa Israelin tähden.',
        13: 'Hebronista tultuaan Daavid oli ottanut Jerusalemista vielä useampia sivuvaimoja ja vaimoja. Daavidille syntyi vielä poikia ja tyttäriä.',
        14: 'Nämä ovat niiden poikien nimet, jotka syntyivät hänelle Jerusalemissa: Sammua, Soobab, Naatan, Salomo,',
        15: 'Jibhar, Elisua, Nefeg, Jaafia,',
        16: 'Elisama, Eljada ja Elifelet.',
        17: 'Kun filistealaiset kuulivat, että Daavid oli voideltu Israelin kuninkaaksi, kaikki filistealaiset lähtivät etsimään Daavidia. Kun Daavid sen kuuli, hän meni alas Vuorilinnaan.',
        18: 'Kun filistealaiset olivat tulleet ja levittäytyneet Refaimin tasangolle,',
        19: 'Daavid kysyi Herralta: "Menenkö filistealaisia vastaan? Annatko heidät käsiini?" Herra sanoi Daavidille: "Mene, sillä tosiaan annan filistealaiset käsiisi."',
        20: 'Daavid tuli Baal-Perasimiin. Siellä Daavid voitti heidät ja sanoi: " Herra on murtanut viholliseni edessäni, niin kuin vedet murtavat." Siitä sen paikan nimeksi tuli Baal-Perasim.',
        21: 'He jättivät siihen epäjumalankuvansa, ja Daavid ja hänen miehensä veivät ne pois.',
        22: 'Filistealaiset tulivat vielä kerran ja levittäytyivät Refaimin tasangolle.',
        23: 'Daavid kysyi Herralta, ja hän vastasi: "Älä mene heitä vastaan, vaan kierrä heidät takaapäin ja hyökkää heidän kimppuunsa balsamipuiden puolelta.',
        24: 'Kun kuulet astunnan kahinan balsamipuiden latvoista, ryntää nopeasti, sillä silloin Herra on käynyt edelläsi tuhotakseen filistealaisten leirin." Daavid teki, niin kuin Herra oli häntä käskenyt, ja hän voitti filistealaiset ja ajoi heitä takaa Gebasta aina Geseriin saakka.',
    },
    6: {
        1: 'Daavid kokosi jälleen kaikki valiomiehet Israelista, kolmekymmentä tuhatta miestä.',
        2: 'Daavid ja kaikki väki, joka oli hänen kanssaan, nousi ja lähti Juudan Baalasta, tuomaan sieltä Jumalan arkkia, jonka Herra Sebaot oli ottanut nimiinsä, hän, jonka istuinta kerubit kannattavat.',
        3: 'He panivat Jumalan arkin uusiin vaunuihin ja veivät sen pois Abinadabin talosta, joka oli mäellä, ja Ussa ja Ahjo, Abinadabin pojat, ohjasivat uusia vaunuja.',
        4: 'He veivät Jumalan arkin pois Abinadabin talosta, joka oli mäellä, kulkien Jumalan arkin mukana, ja Ahjo kulki arkin edellä.',
        5: 'Daavid sekä koko Israelin heimo karkeloi kaikin voimin Herran edessä soittaen kaikilla sypressipuisilla soittimilla, lyyroilla, harpuilla, tamburiineilla, helistimillä ja symbaaleilla.',
        6: 'Kun he tulivat Naakonin puimatantereen luo, Ussa ojensi kätensä Jumalan arkkiin ja tarttui siihen, sillä härät kompastuivat.',
        7: 'Herran viha syttyi Ussaa kohtaan, ja Jumala löi hänet siinä hänen hairahduksensa tähden, niin että hän kuoli siihen Jumalan arkin ääreen.',
        8: 'Mutta Daavid pahastui siitä, että Herra niin oli murtanut Ussan. Siitä paikka sai nimekseen Peres-Ussa aina tähän päivään asti.',
        9: 'Daavid pelästyi sinä päivänä Herraa, niin että hän sanoi: "Kuinka Herran arkki voi tulla luokseni?"',
        10: 'Daavid ei tahtonut siirtää Herran arkkia luokseen Daavidin kaupunkiin, vaan Daavid toimitti sen syrjään gatilaisen Oobed-Edomin taloon.',
        11: 'Herran arkki jäi kolmeksi kuukaudeksi gatilaisen Oobed-Edomin taloon. Herra siunasi Oobed-Edomia ja koko hänen taloaan.',
        12: 'Kun kuningas Daavidille kerrottiin, että Herra oli Jumalan arkin tähden siunannut Oobed-Edomin taloa ja kaikkea, mitä hänellä oli, Daavid meni ja toi riemuiten Jumalan arkin Oobed-Edomin talosta Daavidin kaupunkiin.',
        13: 'Kun Herran arkin kantajat olivat astuneet kuusi askelta, hän uhrasi härän ja juottovasikan.',
        14: 'Daavid hyppi kaikin voimin Herran edessä, ja Daavid oli puettu pellavakasukkaan.',
        15: 'Daavid ja koko Israelin heimo toivat Herran arkin riemun raikuessa ja torvien raikuessa.',
        16: 'Kun Herran arkki tuli Daavidin kaupunkiin, katseli Miikal, Saulin tytär, ikkunasta. Nähdessään kuningas Daavidin karkeloivan ja hyppivän Herran edessä hän halveksi häntä sydämessään.',
        17: 'Kun he olivat tuoneet Herran arkin ja asettaneet sen paikalleen majaan, jonka Daavid oli sille pystyttänyt, Daavid uhrasi polttouhreja ja rauhanuhreja Herran edessä.',
        18: 'Kun Daavid oli uhrannut polttouhrin ja rauhanuhrit, hän siunasi kansan Herran Sebaotin nimeen.',
        19: 'Hän jakoi koko kansalle, koko Israelin joukolle, sekä miehille että naisille, kullekin leipäkakun, palan lihaa ja rypälekakun. Sitten kaikki kansa lähti, kukin kotiinsa.',
        20: 'Kun Daavid palasi takaisin tervehtimään perhettään, Miikal, Saulin tytär, meni ulos Daavidia vastaan ja sanoi: "Kuinka arvokkaana onkaan Israelin kuningas nyt esiintynyt, kun on tänä päivänä paljastanut itsensä palvelijainsa palvelijattarien silmien edessä, niin kuin kevytmielinen ihminen paljastaa itsensä!"',
        21: 'Daavid sanoi Miikalille: " Herran edessä, joka on valinnut minut, ohi isäsi ja koko hänen sukunsa, ja asettanut minut Herran kansan, Israelin, ruhtinaaksi – Herran edessä minä karkeloin.',
        22: 'Tähänkin minä pidän itseni liian vähäisenä ja olen omissa silmissäni halpa. Mutta ne palvelijattaret, joista puhuit, tulevat minua kunnioittamaan."',
        23: 'Miikal, Saulin tytär, ei saanut lasta kuolinpäiväänsä asti.',
    },
    7: {
        1: 'Kerran, kun kuningas istui linnassaan, sitten kun Herra oli suonut hänen päästä rauhaan kaikilta hänen ympärillään olevilta vihollisilta,',
        2: 'kuningas sanoi profeetta Naatanille: "Katso, minä asun setripuisessa linnassa, mutta Jumalan arkki asuu telttakankaan suojassa."',
        3: 'Naatan sanoi kuninkaalle: "Tee vain kaikki, mitä mielessäsi on, sillä Herra on kanssasi."',
        4: 'Mutta sinä yönä tapahtui, että Naatanille tuli tämä Herran sana:',
        5: '"Mene ja sano palvelijalleni Daavidille: Näin sanoo Herra: Sinäkö rakentaisit minulle huoneen asuakseni?',
        6: 'Enhän ole asunut huoneessa siitä päivästä asti, jona johdatin israelilaiset Egyptistä, tähän päivään saakka, vaan olen vaeltanut asuen teltta-asumuksessa.',
        7: 'Olenko koskaan, missä olenkin vaeltanut kaikkien israelilaisten keskuudessa, millekään Israelin sukukunnalle, jonka olen asettanut kaitsemaan kansaani Israelia, sanonut näin: Miksi ette ole rakentaneet minulle setripuista huonetta?',
        8: 'Sano nyt palvelijalleni Daavidille: Näin sanoo Herra Sebaot: Minä olen ottanut sinut laitumelta lammasten jäljestä kansani Israelin ruhtinaaksi.',
        9: 'Olen ollut kanssasi kaikkialla, missä vaelsit, ja olen hävittänyt kaikki vihollisesi tieltäsi. Teen sinulle suuren nimen, suurimpien nimien vertaisen maan päällä.',
        10: 'Valmistan sijan kansalleni Israelille ja istutan sen niin, että se asuu paikallaan eikä enää ole levoton, eivätkä vääryyden tekijät sitä enää sorra kuten ennen,',
        11: 'siitä päivästä saakka, jolloin asetin tuomareita kansalleni Israelille, ja annan sinun päästä rauhaan kaikista vihollisistasi. Herra ilmoittaa sinulle, että Herra on tekevä sinulle huoneen.',
        12: 'Kun päiväsi ovat päättyneet ja lepäät isiesi luona, minä korotan sinun seuraajaksesi jälkeläisesi, joka lähtee ruumiistasi, ja vahvistan hänen kuninkuutensa.',
        13: 'Hän on rakentava huoneen nimelleni, ja vahvistan hänen valtaistuimensa ikuisiksi ajoiksi.',
        14: 'Minä olen oleva hänen Isänsä ja hän minun Poikani, niin että, jos hän tekee väärin, minä rankaisen häntä ihmisvitsalla, niin kuin ihmislapsia lyödään,',
        15: 'mutta armoni ei poistu hänestä, niin kuin poistin sen Saulista, jonka poistin tieltäsi.',
        16: 'Sukusi ja kuninkuutesi pysyvät edessäsi iäti, ja valtaistuimesi on oleva iäti vahva."',
        17: 'Aivan näillä sanoilla ja tämän näyn mukaan Naatan puhui Daavidille.',
        18: 'Kuningas Daavid meni ja asettui Herran eteen ja sanoi: "Mikä olen minä, Herra, Herra, ja mikä on sukuni, että olet saattanut minut tähän asti?',
        19: 'Mutta tämäkin on ollut vähän silmissäsi, Herra Herra, ja niin olet sinä puhunut palvelijasi suvulle myös kaukaisista asioista. Tämä on sen ihmisen tapa, joka on Herra, Herra.',
        20: 'Mitä Daavid enää sinulle puhuisi? Sinähän tunnet palvelijasi, Herra, Herra.',
        21: 'Sanasi tähden ja mielesi mukaan sinä olet tehnyt sen, että ilmoitit palvelijallesi kaikki nämä suuret asiat.',
        22: 'Sen tähden olet sinä, Herra Jumala, suuri. Sillä kaiken sen mukaan, mitä olemme korvillamme kuulleet, ei ole vertaistasi, eikä ole muuta jumalaa kuin sinä.',
        23: 'Missä maan päällä on toista kansaa kansasi Israelin vertaista, jota Jumala itse on käynyt lunastamaan kansakseen tehdäkseen sen nimen kuuluisaksi ja tehdäkseen teille, maallesi, suuria ja pelottavia tekoja kansasi edessä, jonka lunastit itsellesi Egyptistä, pakanoiden ja heidän jumaliensa vallasta?',
        24: 'Olet valmistanut itsellesi kansasi Israelin, omaksi kansaksesi ikiajoiksi, ja sinä, Herra, olet tullut heidän Jumalakseen.',
        25: 'Täytä nyt, Herra Jumala, ikiajoiksi se, mitä olet puhunut palvelijastasi ja hänen suvustaan. Tee, niin kuin olet puhunut.',
        26: 'Nimesi tulee suureksi iankaikkisesti, ja se on oleva: Herra Sebaot, Israelin Jumala. Palvelijasi Daavidin suku on pysyvä edessäsi.',
        27: "Sillä sinä, Herra Sebaot, Israelin Jumala, olet ilmoittanut palvelijallesi ja sanonut: 'Minä rakennan sinulle huoneen.' Siitä palvelijasi on saanut rohkeuden rukoilla tämän rukouksen kuullaksesi.",
        28: 'Nyt, Herra, Herra, sinä olet Jumala, ja sanasi ovat todet. Kun olet luvannut palvelijallesi tämän hyvän,',
        29: 'suvaitse nyt siunata palvelijasi sukua, että se pysyisi iäti edessäsi. Sillä sinä, Herra, Herra, olet sen luvannut, ja palvelijasi suku on oleva siunattu siunauksellasi iankaikkisesti."',
    },
    8: {
        1: 'Sen jälkeen Daavid löi filistealaiset ja alisti heidät valtaansa. Daavid otti vallan ohjat filistealaisten käsistä.',
        2: 'Hän voitti myös mooabilaiset ja mittasi heitä nuoralla pantuaan heidät makaamaan maahan: aina kaksi nuoranpituutta hän mittasi surmattavaksi ja yhden nuoranpituuden henkiin jätettäväksi. Mooabilaiset tulivat Daavidin veronalaisiksi palvelijoiksi.',
        3: 'Samoin Daavid voitti Hadadeserin, Rehobin pojan, Sooban kuninkaan, kun tämä oli lähtenyt palauttamaan valtaansa Eufratille ulottuvia alueita.',
        4: 'Daavid otti häneltä vangiksi tuhat seitsemänsataa ratsumiestä ja kaksikymmentä tuhatta jalkamiestä ja katkoi kaikilta vaunuhevosilta vuohisjänteet. Ainoastaan sata vaunuhevosta hän niistä säästi.',
        5: 'Kun Damaskon aramilaiset tulivat auttamaan Hadadeseria, Sooban kuningasta, Daavid voitti kaksikymmentä kaksi tuhatta aramilaista.',
        6: 'Daavid asetti maaherroja Damaskon Aramiin, ja aramilaiset tulivat Daavidin veronalaisiksi palvelijoiksi. Herra antoi Daavidille voiton, mihin tahansa hän meni.',
        7: 'Daavid otti ne kultakilvet, jotka Hadadeserin palvelijoilla oli, ja vei ne Jerusalemiin.',
        8: 'Hadadeserin kaupungeista, Betahista ja Beerotaista, kuningas Daavid otti sangen paljon vaskea.',
        9: 'Kun Tooi, Hamatin kuningas, kuuli, että Daavid oli voittanut Hadadeserin koko sotajoukon,',
        10: 'Tooi lähetti poikansa Jooramin kuningas Daavidin luo tervehtimään häntä ja onnittelemaan häntä siitä, että hän oli taistellut Hadadeserin kanssa ja voittanut hänet, sillä Hadadeser oli ollut Tooin vastustaja. Hänellä oli mukanaan hopea-, kulta- ja vaskiesineitä.',
        11: 'Nekin kuningas Daavid pyhitti Herralle, samoin kuin oli pyhittänyt sen hopean ja kullan, minkä hän oli ottanut kaikilta kukistamiltaan kansoilta:',
        12: 'Aramilta, Mooabilta, ammonilaisilta, filistealaisilta ja Amalekilta, sekä sen saaliin, minkä hän oli ottanut Hadadeserilta, Rehobin pojalta, Sooban kuninkaalta.',
        13: 'Daavid teki nimensä kuuluisaksi, kun hän palasi takaisin voitettuaan Suolalaaksossa edomilaiset, kahdeksantoista tuhatta miestä.',
        14: 'Hän asetti maaherroja Edomiin. Koko Edomiin hän asetti maaherrat, ja kaikki edomilaiset tulivat Daavidin palvelijoiksi. Herra antoi Daavidille voiton, mihin tahansa tämä meni.',
        15: 'Niin Daavid hallitsi koko Israelia, ja Daavid teki kaikelle kansalleen sitä, mikä oikeus ja vanhurskaus on.',
        16: 'Jooab, Serujan poika, oli sotajoukon ylipäällikkönä, ja Joosafat, Ahiludin poika, oli kanslerina.',
        17: 'Saadok, Ahitubin poika, ja Ahimelek, Ebjatarin poika, olivat pappeina, ja Seraja oli kirjurina.',
        18: 'Benaja, Joojadan poika, oli kreettien ja pleettien päällikkönä. Daavidin pojat olivat myös pappeina.',
    },
    9: {
        1: 'Daavid kysyi: "Onko Saulin suvusta enää jäljellä ketään, jolle voin tehdä laupeuden Joonatanin tähden?"',
        2: 'Saulin perheessä oli ollut palvelija nimeltä Siiba, ja hänet he kutsuivat Daavidin eteen. Kuningas sanoi hänelle: "Oletko sinä Siiba?" Hän vastasi: "Palvelijasi on."',
        3: 'Kuningas kysyi: "Eikö Saulin suvusta ole enää jäljellä ketään, jolle voisin tehdä Jumalan laupeuden?" Siiba vastasi kuninkaalle: "Vielä on Joonatanin poika, joka on rampa jaloistaan."',
        4: 'Kuningas kysyi häneltä: "Missä hän on?" Siiba vastasi kuninkaalle: "Hän on Maakirin, Ammielin pojan, talossa Loodebarissa."',
        5: 'Kuningas Daavid lähetti noutamaan hänet Maakirin, Ammielin pojan, talosta Loodebarista.',
        6: 'Kun Mefiboset, Saulin pojan Joonatanin poika, tuli Daavidin luo, lankesi hän kasvoilleen ja osoitti kunnioitusta. Niin Daavid sanoi: "Mefiboset!" Hän vastasi: "Tässä on palvelijasi."',
        7: 'Daavid sanoi hänelle: "Älä pelkää, sillä teen todellakin sinulle laupeuden isäsi Joonatanin tähden, ja minä palautan sinulle isoisäsi Saulin kaiken maaomaisuuden, ja sinä aterioit aina pöydässäni."',
        8: 'Niin tämä kumarsi ja sanoi: "Mikä on palvelijasi, että käännyt minunlaiseni koiranraadon puoleen?"',
        9: 'Sitten kuningas kutsui Siiban, Saulin palvelijan, ja sanoi hänelle: "Kaiken, mikä on ollut Saulin ja koko hänen sukunsa omaa, annan herrasi pojalle.',
        10: 'Viljele sinä poikinesi ja palvelijoinesi hänelle sitä maata ja korjaa sato, että herrasi pojalla olisi leipää syödä. Kuitenkin Mefiboset, herrasi poika, aterioi aina pöydässäni." Siiballa oli viisitoista poikaa ja kaksikymmentä palvelijaa.',
        11: 'Siiba sanoi kuninkaalle: "Aivan kuten herrani, kuningas, käskee palvelijaansa, palvelijasi tekee." – "Niin Mefiboset on syövä pöydässäni, niin kuin hän olisi kuninkaan poikia."',
        12: 'Mefibosetilla oli pieni poika nimeltä Miika. Koko Siiban talonväki oli Mefibosetin palvelijoita.',
        13: 'Mutta Mefiboset asui Jerusalemissa, koska hän aina söi kuninkaan pöydässä. Hän ontui kumpaakin jalkaansa.',
    },
    10: {
        1: 'Tapahtui sen jälkeen, että ammonilaisten kuningas kuoli, ja hänen poikansa Haanun tuli kuninkaaksi hänen jälkeensä.',
        2: 'Daavid sanoi: "Minä osoitan laupeutta Haanunille, Naahaan pojalle, niin kuin hänen isänsä osoitti laupeutta minulle." Sitten Daavid lähetti palvelijoitaan lohduttamaan häntä hänen isänsä kuoleman johdosta. Kun Daavidin palvelijat tulivat ammonilaisten maahan,',
        3: 'sanoivat ammonilaisten päämiehet herralleen Haanunille: "Luuletko, että Daavid tahtoo kunnioittaa isääsi, kun hän lähettää lohduttajia luoksesi? Varmasti Daavid on lähettänyt palvelijansa luoksesi tutkimaan kaupunkia, vakoilemaan ja hävittämään sitä."',
        4: 'Haanun otatti kiinni Daavidin palvelijat, ajatti toisen puolen heidän partaansa ja leikkautti toisen puolen heidän vaatteistaan, niiden takaosia myöten, ja päästi heidät sitten menemään.',
        5: 'Kun se ilmoitettiin Daavidille, hän lähetti sanan heitä vastaan, sillä miehiä oli pahasti häväisty. Kuningas käski sanoa: "Jääkää Jerikoon, kunnes partanne on kasvanut, ja tulkaa sitten takaisin."',
        6: 'Kun ammonilaiset näkivät joutuneensa Daavidin vihoihin, ammonilaiset lähettivät lähettiläitä ja palkkasivat Beet-Rehobin ja Sooban aramilaisia, kaksikymmentä tuhatta jalkamiestä, ja Maakan kuninkaalta tuhat miestä ja Toobin miehiä kaksitoista tuhatta.',
        7: 'Kun Daavid sen kuuli, hän lähetti Jooabin ja koko sotajoukon, kaikki valiot.',
        8: 'Niin ammonilaiset lähtivät ja asettuivat rintamaan portin oven edustalle, mutta Sooban ja Rehobin aramilaiset ja Toobin ja Maakan miehet olivat eri joukkona kedolla.',
        9: 'Kun Jooab näki, että häntä uhkasi hyökkäys edestä ja takaa, hän valitsi miehiä kaikista Israelin valiomiehistä ja asettui rintamaan aramilaisia vastaan.',
        10: 'Mutta muun väen hän antoi veljensä Abisain johtoon, ja tämä asettui rintamaan ammonilaisia vastaan.',
        11: 'Hän sanoi: "Jos aramilaiset tulevat minulle ylivoimaisiksi, tule avukseni. Jos taas ammonilaiset tulevat sinulle ylivoimaisiksi, minä tulen sinua auttamaan.',
        12: 'Ole luja, ja pysykäämme lujina kansamme puolesta ja Jumalamme kaupunkien puolesta. Tehköön sitten Herra, minkä hyväksi näkee."',
        13: 'Sitten Jooab ja väki, joka oli hänen kanssaan, ryhtyi taisteluun aramilaisia vastaan, ja nämä pakenivat häntä.',
        14: 'Kun ammonilaiset näkivät aramilaisten pakenevan, hekin pakenivat Abisaita ja menivät kaupunkiin. Sitten Jooab palasi ahdistamasta ammonilaisia ja tuli Jerusalemiin.',
        15: 'Kun aramilaiset näkivät, että Israel oli voittanut heidät, he kaikki kokoontuivat,',
        16: 'ja Hadareser lähetti nostattamaan niitä aramilaisia, jotka asuivat tuolla puolella Eufrat-virran. He tulivat Heelamiin, ja Soobak, Hadareserin sotapäällikkö, johti heitä.',
        17: 'Kun se ilmoitettiin Daavidille, hän kokosi kaiken Israelin ja meni Jordanin yli ja tuli Heelamiin. Aramilaiset taas asettuivat sotarintaan Daavidia vastaan ja taistelivat häntä vastaan.',
        18: 'Mutta aramilaiset pakenivat Israelia, ja Daavid surmasi aramilaisilta seitsemän sataa vaunuhevosta ja neljäkymmentä tuhatta ratsumiestä, ja heidän sotapäällikkönsä Soobakin hän löi siellä kuoliaaksi.',
        19: 'Kun kaikki Hadareserin alaiset kuninkaat näkivät, että Israel oli voittanut heidät, he tekivät Israelin kanssa rauhan ja palvelivat heitä. Sen jälkeen aramilaiset eivät enää uskaltaneet auttaa ammonilaisia.',
    },
    11: {
        1: 'Vuoden vaihteessa kuningasten sotaan lähtöaikaan Daavid lähetti Jooabin ja hänen kanssaan palvelijansa ja koko Israelin sotaretkelle. He hävittivät ammonilaisten maata ja piirittivät Rabbaa. Mutta Daavid itse jäi Jerusalemiin.',
        2: 'Niin tapahtui eräänä iltana, kun Daavid oli noussut vuoteeltaan ja käveli kuninkaan linnan katolla, että hän näki katolta naisen peseytymässä, ja nainen oli näöltään hyvin ihana.',
        3: 'Daavid lähetti hankkimaan tietoja naisesta, ja sanottiin: "Se on Batseba, Eliamin tytär, heettiläisen Uurian vaimo."',
        4: 'Daavid lähetti sanansaattajat häntä noutamaan. Hän tuli hänen luokseen, ja Daavid makasi naisen kanssa, joka juuri oli puhdistautunut saastaisuudestaan. Sitten tämä palasi kotiinsa.',
        5: 'Vaimo tuli raskaaksi, ja hän lähetti ilmoittamaan Daavidille: "Minä olen raskaana."',
        6: 'Silloin Daavid lähetti Jooabille sanan: "Lähetä luokseni heettiläinen Uuria." Jooab lähetti Uurian Daavidin luo.',
        7: 'Kun Uuria tuli Daavidin luo, tämä kysyi, kuinka Jooab ja väki voivat ja kuinka sota menestyi.',
        8: 'Daavid sanoi Uurialle: "Mene kotiisi ja pese jalkasi." Uuria lähti kuninkaan linnasta, ja kuninkaan lahja seurasi häntä.',
        9: 'Mutta Uuria menikin maata kuninkaan linnan oven eteen kaikkien muiden herransa palvelijain joukkoon eikä mennyt kotiinsa.',
        10: 'Kun Daavidille ilmoitettiin: "Uuria ei ole mennytkään kotiinsa", Daavid sanoi Uurialle: "Tulethan sinä matkalta, mikset mennyt kotiisi?"',
        11: 'Mutta Uuria sanoi Daavidille: "Arkki ja Israel ja Juuda asuvat lehtimajoissa, herrani Jooab ja herrani palvelijat ovat leiriytyneinä kedolla. Menisinkö minä kotiin syömään, juomaan ja makaamaan vaimoni kanssa? Niin totta kuin sinä elät ja sinun sielusi elää: sitä minä en tee."',
        12: 'Daavid sanoi Uurialle: "Jää tänne vielä täksi päiväksi, huomenna päästän sinut menemään." Uuria jäi Jerusalemiin vielä siksi päiväksi. Seuraavana päivänä',
        13: 'Daavid kutsui hänet luokseen syömään ja juomaan ja juotti hänet juovuksiin. Mutta illalla hän meni maata vuoteelleen herransa palvelijain joukkoon eikä mennyt kotiinsa.',
        14: 'Seuraavana aamuna Daavid kirjoitti kirjeen Jooabille ja lähetti sen Uurian mukana.',
        15: 'Kirjeessä hän kirjoitti näin: "Pankaa Uuria eturintaan kiivaimpaan taisteluun ja vetäytykää takaisin hänen luotaan, että hänet lyötäisiin kuoliaaksi."',
        16: 'Piirittäessään kaupunkia Jooab asetti Uurian siihen paikkaan, missä tiesi urhoollisimpien miesten olevan.',
        17: 'Kun sitten kaupungin miehet ryntäsivät ulos ja ryhtyivät taisteluun Jooabin kanssa, niin väkeä, Daavidin palvelijoita, kaatui, ja myös heettiläinen Uuria kuoli.',
        18: 'Jooab lähetti ilmoittamaan Daavidille kaikki, mitä taistelussa oli tapahtunut.',
        19: 'Hän käski sanansaattajaa sanoen: "Kun olet kertonut kuninkaalle kaiken, mitä sodassa on tapahtunut,',
        20: "kuningas ehkä kiivastuu ja sanoo sinulle: 'Miksi menitte niin lähelle kaupunkia taistelemaan? Ettekö tienneet, että ne ampuvat muurilta?",
        21: 'Kuka surmasi Abimelekin, Jerubbesetin pojan? Eikö nainen heittänyt muurilta jauhinkiven hänen päälleen, niin että hän kuoli Teebeksessä? Miksi menitte niin lähelle muuria?\' Sano silloin: \'Myös palvelijasi heettiläinen Uuria on kuollut.\'"',
        22: 'Sanansaattaja lähti, ja tultuaan hän ilmoitti Daavidille kaiken, mitä Jooab oli lähettänyt hänet ilmoittamaan.',
        23: 'Sanansaattaja sanoi Daavidille: "Ne miehet olivat meille ylivoimaiset ja ryntäsivät meitä vastaan ulos kedolle, mutta työnsimme heidät takaisin portin ovelle saakka.',
        24: 'Silloin ampujat ampuivat muurilta palvelijoitasi, ja kuninkaan palvelijoita kuoli, myös palvelijasi heettiläinen Uuria kuoli."',
        25: 'Silloin Daavid sanoi sanansaattajalle: "Sano näin Jooabille: \'Älä pane sitä pahaksesi, sillä miekka syö milloin yhden, milloin toisen. Taistele urheasti kaupunkia vastaan ja hävitä se.\' Rohkaise häntä näin."',
        26: 'Kun Uurian vaimo kuuli, että hänen miehensä Uuria oli kuollut, hän piti puolisolleen valittajaiset.',
        27: 'Mutta kun suruaika oli ohi, Daavid lähetti ottamaan hänet linnaansa, ja hän tuli hänen vaimokseen. Sitten hän synnytti hänelle pojan. Mutta se, minkä Daavid oli tehnyt, oli paha Herran silmissä.',
    },
    12: {
        1: 'Herra lähetti Naatanin Daavidin luo. Kun hän tuli hänen luokseen, hän sanoi hänelle: "Kaksi miestä oli samassa kaupungissa, toinen rikas ja toinen köyhä.',
        2: 'Rikkaalla oli lampaita ja nautoja hyvin paljon.',
        3: 'Mutta köyhällä ei ollut muuta kuin yksi ainoa pieni karitsa, jonka hän oli ostanut. Hän elätti sitä, ja se kasvoi hänen luonaan yhdessä hänen lastensa kanssa: se söi hänen leipäpalastaan, joi hänen maljastaan, makasi hänen sylissään ja oli hänelle kuin tytär.',
        4: 'Rikkaalle miehelle tuli vieras. Mutta hän ei raskinut ottaa omia lampaitaan eikä nautojaan valmistaakseen ruokaa matkamiehelle, joka oli tullut hänen luokseen, vaan hän otti köyhän miehen karitsan ja valmisti sen miehelle, joka oli tullut hänen luokseen."',
        5: 'Daavid vihastui kovin siihen mieheen ja sanoi Naatanille: "Niin totta kuin Herra elää: mies, joka on tämän tehnyt, on kuoleman oma.',
        6: 'Mutta karitsa hänen on korvattava nelinkertaisesti, koska hän teki näin ja koska hän ei tuntenut sääliä."',
        7: 'Naatan sanoi Daavidille: "Sinä olet se mies. Näin sanoo Herra, Israelin Jumala: \'Minä olen voidellut sinut Israelin kuninkaaksi ja pelastanut sinut Saulin käsistä.',
        8: 'Olen antanut sinulle herrasi linnan ja antanut herrasi vaimot syliisi. Olen antanut sinulle Israelin ja Juudan heimot. Jos tämä olisi vähän, antaisin sinulle vielä sekä sitä että tätä.',
        9: 'Miksi olet pitänyt halpana Herran sanan ja tehnyt sitä, mikä on pahaa hänen silmissään? Heettiläisen Uurian olet surmannut miekalla, olet tappanut hänet ammonilaisten miekalla, ja hänen vaimonsa olet ottanut vaimoksesi.',
        10: 'Sen tähden miekka ei ole milloinkaan väistyvä suvustasi, koska olet pitänyt halpana minut ja ottanut vaimoksesi heettiläisen Uurian vaimon.',
        11: 'Näin sanoo Herra: Katso, minä nostatan sinulle onnettomuuden omasta perheestäsi, ja silmiesi edessä otan vaimosi ja annan heidät toiselle, ja hän on makaava vaimojesi kanssa tämän auringon nähden.',
        12: 'Sillä sinä olet tehnyt tekosi salassa, mutta minä teen tämän koko Israelin ja auringon nähden.\'"',
        13: 'Daavid sanoi Naatanille: "Olen tehnyt syntiä Herraa vastaan." Naatan sanoi Daavidille: "Niin on myös Herra antanut syntisi anteeksi. Sinä et kuole.',
        14: 'Mutta koska tällä teolla olet saattanut Herran viholliset pilkkaamaan häntä, niin se poika, joka sinulle on syntynyt, kuolee."',
        15: 'Naatan meni kotiinsa. Herra löi lasta, jonka Uurian vaimo oli Daavidille synnyttänyt, että se sairastui vaikeasti.',
        16: 'Silloin Daavid etsi Jumalaa pojan tähden, ja Daavid paastosi, ja aina kun hän tuli kotiinsa, makasi hän yötä paljaalla maalla.',
        17: 'Hänen hovinsa vanhimmat menivät hänen luokseen saadakseen hänet nousemaan ylös maasta, mutta hän ei tahtonut, eikä hän syönyt mitään heidän kanssaan.',
        18: 'Seitsemäntenä päivänä lapsi kuoli. Mutta Daavidin palvelijat eivät uskaltaneet ilmoittaa hänelle, että lapsi oli kuollut, sillä he ajattelivat: "Katso, kun me puhuimme hänelle lapsen vielä eläessä, hän ei kuullut meitä. Kuinka voisimme sitten sanoa hänelle, että lapsi on kuollut? Hän voisi tehdä itselleen pahaa."',
        19: 'Mutta kun Daavid näki, että hänen palvelijansa kuiskailivat keskenään, hän käsitti, että lapsi oli kuollut. Silloin Daavid kysyi palvelijoiltaan: "Onko lapsi kuollut?" He vastasivat: "On."',
        20: 'Niin Daavid nousi maasta, peseytyi ja voiteli itsensä, muutti vaatteensa, meni Herran huoneeseen ja rukoili. Kun hän tuli kotiinsa, hän pyysi ruokaa, ja he tarjosivat, ja hän söi.',
        21: 'Mutta hänen palvelijansa sanoivat hänelle: "Miksi teet näin? Lapsen eläessä sinä paastosit ja itkit, mutta lapsen kuoltua sinä nouset ja syöt."',
        22: 'Hän vastasi: "Kun lapsi vielä eli, paastosin minä ja itkin, sillä ajattelin: Kenties Herra on minulle armollinen, niin että lapsi jää eloon.',
        23: 'Mutta kun hän nyt on kuollut, niin mitä minä enää paastoaisin? Enhän minä enää voi palauttaa häntä. Minä menen hänen luokseen, mutta hän ei enää palaa minun luokseni."',
        24: 'Daavid lohdutti vaimoaan Batsebaa ja meni hänen luokseen ja makasi hänen kanssaan. Sitten tämä synnytti pojan, ja hän antoi tälle nimen Salomo, ja Herra rakasti häntä.',
        25: 'Daavid lähetti sanoman profeetta Naatanin välityksellä, ja tämä kutsui häntä Jedidjaksi Herran tähden.',
        26: 'Mutta Jooab ryhtyi taistelemaan ammonilaisten Rabbaa vastaan ja valloitti kuninkaan kaupungin.',
        27: 'Jooab lähetti sanansaattajat Daavidin luo ja käski sanoa: "Olen ryhtynyt taisteluun Rabbaa vastaan ja olen jo valloittanut vesikaupungin.',
        28: 'Niin kokoa nyt jäljellä oleva väki ja asetu leiriin kaupungin edustalle ja valloita se, etten minä sitä valloittaisi ja ottaisi sitä nimiini."',
        29: 'Silloin Daavid kokosi kaiken väen ja lähti Rabbaan, ryhtyi taisteluun sitä vastaan ja valloitti sen.',
        30: 'Hän otti heidän kuninkaansa kruunun hänen päästään – se painoi talentin kultaa, ja siinä oli kallis kivi – ja se pantiin Daavidin päähän. Hän vei sangen paljon saalista kaupungista.',
        31: 'Hän vei pois myös kansan, mitä siellä oli, ja asetti heitä kivisahojen ja rautahakkujen ja rautakirveiden ääreen ja pani heitä tiilentekoon. Näin hän teki kaikille ammonilaisten kaupungeille. Sitten Daavid ja kaikki väki palasi Jerusalemiin.',
    },
    13: {
        1: 'Sen jälkeen tapahtui tämä. Daavidin pojalla Absalomilla oli kaunis sisar nimeltä Taamar, ja Daavidin poika Amnon rakastui häneen.',
        2: 'Amnon tuli aivan sairaaksi tuskasta sisarensa Taamarin tähden. Sillä kun tämä oli neitsyt, näytti Amnonista mahdottomalta tehdä hänelle mitään.',
        3: 'Mutta Amnonilla oli ystävä, nimeltä Joonadab, Daavidin veljen Simean poika, ja Joonadab oli hyvin ovela mies.',
        4: 'Tämä sanoi hänelle: "Miksi sinä kuihdut noin joka aamu, kuninkaan poika? Etkö ilmaise minulle sitä?" Amnon vastasi hänelle: "Minä olen rakastunut veljeni Absalomin sisareen Taamariin."',
        5: 'Joonadab sanoi hänelle: "Paneudu vuoteeseesi ja tekeydy sairaaksi. Kun isäsi tulee katsomaan sinua, sano hänelle: \'Salli minun sisareni Taamarin tulla antamaan minulle jotain syötävää. Jos hän valmistaisi ruuan silmieni edessä, että minä näkisin sen, niin söisin hänen kädestään.\'"',
        6: 'Amnon paneutui maata ja tekeytyi sairaaksi. Kun kuningas tuli katsomaan häntä, Amnon sanoi kuninkaalle: "Salli sisareni Taamarin tulla tekemään kaksi kakkua silmieni edessä, niin minä syön hänen kädestään."',
        7: 'Silloin Daavid lähetti sanan Taamarille linnaan ja käski sanoa hänelle: "Mene veljesi Amnonin taloon ja valmista hänelle ruokaa."',
        8: 'Niin Taamar meni veljensä Amnonin taloon, jossa tämä makasi. Hän otti taikinaa, sotki ja teki leipäkakkuja hänen silmiensä edessä ja paistoi kakut,',
        9: 'otti pannun ja kaatoi hänen eteensä, mutta tämä ei tahtonut syödä. Amnon sanoi: "Toimittakaa kaikki luotani ulos." Niin kaikki lähtivät hänen luotaan ulos.',
        10: 'Sitten Amnon sanoi Taamarille: "Tuo ruoka tänne sisähuoneeseen syödäkseni kädestäsi." Taamar otti tekemänsä kakut ja toi ne sisähuoneeseen veljelleen Amnonille.',
        11: 'Mutta kun hän tarjosi niitä tälle syödä, tämä tarttui häneen ja sanoi hänelle: "Tule, makaa kanssani, sisareni!"',
        12: 'Hän sanoi: "Pois se, veljeni, älä tee minulle väkivaltaa, sillä semmoista ei saa tehdä Israelissa. Älä tee sellaista häpeällistä tekoa.',
        13: 'Mihin minä joutuisin häpeäni kanssa? Ja sinua pidettäisiin Israelissa houkkana. Puhu nyt kuninkaan kanssa, hän ei minua sinulta kiellä."',
        14: 'Mutta tämä ei tahtonut kuulla häntä, vaan voitti hänet, teki hänelle väkivaltaa ja makasi hänet.',
        15: 'Mutta sitten valtasi Amnonin hyvin suuri vastenmielisyys häntä kohtaan. Vastenmielisyys häntä kohtaan oli suurempi kuin rakkaus, jolla hän oli häntä rakastanut. Amnon sanoi hänelle: "Nouse, mene tiehesi."',
        16: 'Hän sanoi hänelle: "Eikö tämä rikos, että ajat minut pois, ole vielä suurempi kuin se toinen, jonka olet minulle tehnyt?" Mutta hän ei tahtonut kuulla häntä,',
        17: 'vaan kutsui nuoren miehen, joka häntä palveli, ja sanoi: "Ajakaa ulos luotani tämä, ja lukitse ovi hänen jälkeensä."',
        18: 'Tytöllä oli yllään pitkäliepeinen, hihallinen ihokas. Sillä sellaisiin viittoihin olivat kuninkaan tyttäret puetut neitsyenä ollessaan. Kun palvelija oli vienyt hänet ulos ja lukinnut oven hänen jälkeensä,',
        19: 'Taamar otti tuhkaa päänsä päälle ja repäisi rikki pitkäliepeisen, hihallisen paidan, joka hänellä oli yllään, pani kätensä päänsä päälle ja käveli huutaen lakkaamatta.',
        20: 'Hänen veljensä Absalom sanoi hänelle: "Onko veljesi Amnon ollut kanssasi? Vaikene nyt, sisareni, onhan hän veljesi. Älä pane tätä asiaa niin sydämellesi." Taamar jäi hylättynä veljensä Absalomin taloon.',
        21: 'Kun kuningas Daavid kuuli kaiken tämän, hän vihastui kovin.',
        22: 'Mutta Absalom ei puhunut Amnonille sanaakaan, ei pahaa eikä hyvää, sillä Absalom vihasi Amnonia sen tähden, että tämä oli tehnyt väkivaltaa hänen sisarelleen Taamarille.',
        23: 'Kahden vuoden kuluttua tapahtui, että Absalomilla oli lammasten keritsiäiset Baal-Haasorissa, joka on Efraimin luona. Absalom kutsui sinne kaikki kuninkaan pojat.',
        24: 'Absalom tuli kuninkaan luo ja sanoi: "Katso, palvelijallasi on lammasten keritsiäiset. Jospa kuningaskin palvelijoineen tulisi palvelijansa luo."',
        25: 'Mutta kuningas vastasi Absalomille: "Ei niin, poikani, älkäämme tulko kaikki, ettemme olisi sinulle vaivaksi." Vaikka hän pyytämällä pyysi häntä, hän ei kuitenkaan tahtonut mennä, vaan siunasi hänet.',
        26: 'Silloin Absalom sanoi: "Jollet itse tulekaan, lähteköön kuitenkin veljeni Amnon kanssamme." Kuningas sanoi hänelle: "Miksi juuri hänen olisi mentävä kanssasi?"',
        27: 'Mutta kun Absalom vaati häntä, hän päästi Amnonin ja kaikki muut kuninkaan pojat menemään hänen kanssaan.',
        28: 'Absalom käski palvelijoitaan ja sanoi: "Pitäkää silmällä, milloin Amnonin sydän tulee iloiseksi viinistä, ja kun minä sanon teille: \'Surmatkaa Amnon\', niin tappakaa hänet älkääkä pelätkö, sillä minä olen teitä käskenyt. Olkaa lujat ja urhoolliset."',
        29: 'Absalomin palvelijat tekivät Amnonille, kuten Absalom oli käskenyt. Silloin kaikki kuninkaan pojat nousivat, istuivat kukin muulinsa selkään ja pakenivat.',
        30: 'Heidän vielä ollessaan matkalla tuli Daavidille sanoma: "Absalom on surmannut kaikki kuninkaan pojat, niin ettei ainoatakaan ole jäänyt heistä jäljelle."',
        31: 'Silloin kuningas nousi, repäisi vaatteensa ja paneutui maahan maata, ja kaikki hänen palvelijansa seisoivat siinä reväistyin vaattein.',
        32: 'Joonadab, Daavidin veljen Simean poika, vastasi ja sanoi: "Älköön herrani luulko, että kaikki nuoret miehet, kuninkaan pojat, ovat tapetut, ainoastaan Amnon on kuollut. Sillä ilme Absalomin kasvoilla on tiennyt pahaa siitä päivästä lähtien, jona Amnon teki väkivaltaa hänen sisarelleen Taamarille.',
        33: 'Älköön siis herrani, kuningas, panko sydämelleen sitä puhetta, että muka kaikki kuninkaan pojat olisivat kuolleet, sillä ainoastaan Amnon on kuollut."',
        34: 'Mutta Absalom pakeni. Kun palvelija, joka oli tähystäjänä, nosti silmänsä ja katseli, katso, paljon väkeä tuli tietä pitkin vuoren rinnettä, joka oli hänen takanaan.',
        35: 'Silloin Joonadab sanoi kuninkaalle: "Katso, kuninkaan pojat tulevat. On tapahtunut, niin kuin palvelijasi sanoi."',
        36: 'Juuri kun hän oli saanut sen sanotuksi, katso, kuninkaan pojat tulivat ja korottivat äänensä ja itkivät. Myös kuningas ja kaikki hänen palvelijansa itkivät hyvin katkerasti.',
        37: 'Mutta Absalom oli paennut ja mennyt Gesurin kuninkaan Talmain, Ammihudin pojan, luo. Daavid suri poikaansa kaiken aikaa.',
        38: 'Kun Absalom oli paennut ja tullut Gesuriin, hän jäi sinne kolmeksi vuodeksi.',
        39: 'Mutta kuningas Daavid ikävöi päästä Absalomin luo, sillä hän oli lohduttautunut Amnonin kuolemasta.',
    },
    14: {
        1: 'Kun Jooab, Serujan poika, huomasi, että kuninkaan sydän oli kääntynyt Absalomin puoleen,',
        2: 'Jooab lähetti noutamaan Tekoasta taitavan naisen ja sanoi hänelle: "Ole surevinasi ja pukeudu suruvaatteisiin äläkä voitele itseäsi öljyllä, vaan ole kuin vaimo, joka jo kauan on surrut vainajaa.',
        3: 'Mene kuninkaan eteen ja puhu hänelle näin." Sitten Jooab pani sanat hänen suuhunsa.',
        4: 'Tekoalainen nainen meni kuninkaan eteen, lankesi kasvoilleen maahan ja osoitti kunnioitusta ja sanoi: "Auta, kuningas!"',
        5: 'Kuningas sanoi hänelle: "Mikä sinun on?" Hän vastasi: "Totisesti, minä olen leskivaimo. Mieheni on kuollut.',
        6: 'Palvelijattarellasi oli kaksi poikaa. He tulivat riitaan keskenään kedolla, eikä siellä ollut ketään, joka olisi sovittanut heidän välinsä, ja toinen löi toisen kuoliaaksi.',
        7: 'Katso, koko suku on noussut palvelijatartasi vastaan, ja he sanovat: \'Anna tänne veljensä surmaaja, että otamme häneltä hengen hänen tapetun veljensä hengestä ja hävitämme perillisenkin.\' He sammuttaisivat kipinänkin, joka minulla vielä on jäljellä, ettei miehestäni jäisi nimeä eikä jälkeläistä maan päälle."',
        8: 'Kuningas sanoi vaimolle: "Mene kotiisi, minä annan käskyn sinusta."',
        9: 'Mutta tekoalainen nainen sanoi kuninkaalle: "Herrani, kuningas, tulkoon tämä rikos minun ja minun isäni perheen kannettavaksi, mutta kuningas ja hänen valtaistuimensa olkoon siitä vapaa."',
        10: 'Kuningas sanoi: "Tuo minun eteeni se, joka puhuu sinulle noin, niin hän ei enää sinuun koske."',
        11: 'Nainen sanoi: "Muistakoon kuningas Herraa Jumalaansa, ettei verenkostaja saisi tuottaa vielä suurempaa turmiota, ja ettei poikaani tuhottaisi." Hän sanoi: "Niin totta kuin Herra elää: ei hiuskarvakaan poikasi päästä ole putoava maahan."',
        12: 'Mutta nainen sanoi: "Salli palvelijattaresi puhua vielä sananen herralleni, kuninkaalle." Hän vastasi: "Puhu."',
        13: 'Nainen sanoi: "Miksi sinä ajattelet tehdä juuri samoin Jumalan kansaa vastaan, koskapa kuningas ei salli oman hylkäämänsä tulla takaisin? Noin puhuessaanhan kuningas itse joutuu ikään kuin syylliseksi.',
        14: 'Mehän kuolemme ja olemme kuin maahan kaadettu vesi, jota ei voi koota takaisin. Mutta Jumala ei ota pois elämää, vaan sitä hän ajattelee, ettei vain hylätty joutuisi hänestä erotetuksi.',
        15: 'Sen tähden tulin nyt puhumaan tätä herralleni, kuninkaalle, kun kansa sai minut pelkäämään. Palvelijattaresi ajatteli: puhun kuninkaalle, ehkä kuningas tekee palvelijattarensa sanan mukaan.',
        16: 'Kuningas on kuuleva ja pelastava palvelijattarensa sen miehen kourista, joka tahtoo hävittää sekä minut että poikani Jumalan perintöosasta.',
        17: 'Palvelijattaresi ajatteli: herrani kuninkaan sana on rauhoittava minut. Sillä herrani kuningas on Jumalan enkelin kaltainen, niin että hän kuulee, mikä on hyvää ja mikä pahaa. Herra, Jumalasi, olkoon kanssasi',
        18: 'Kuningas vastasi ja sanoi naiselle: "Älä salaa minulta mitään, mitä minä sinulta kysyn." Vaimo sanoi: "Herrani, kuningas, puhukoon."',
        19: 'Kuningas kysyi: "Eikö Jooabin käsi ole mukanasi kaikessa tässä?" Vaimo vastasi ja sanoi: "Niin totta kuin sielusi, herrani kuningas elää: ei pääse oikeaan eikä vasempaan siitä, mitä herrani kuningas, puhuu. Palvelijasi Jooab on käskenyt minua tähän ja pannut kaikki nämä sanat palvelijattaresi suuhun.',
        20: 'Antaakseen asialle toisen muodon on palvelijasi Jooab näin tehnyt, mutta herrani on viisas kuin Jumalan enkeli ja tietää kaiken, mitä maan päällä tapahtuu."',
        21: 'Kuningas sanoi Jooabille: "Katso, tämän minä teen: mene ja tuo takaisin nuorukainen Absalom."',
        22: 'Jooab lankesi kasvoilleen maahan, osoitti kunnioitusta ja siunasi kuningasta. Jooab sanoi: "Nyt palvelijasi tietää, että olen löytänyt armon silmiesi edessä, herrani, kuningas, koska kuningas tekee palvelijansa sanan mukaan."',
        23: 'Jooab nousi ja meni Gesuriin ja toi Absalomin Jerusalemiin.',
        24: 'Kuningas sanoi: "Hän siirtyköön omaan taloonsa, mutta älköön tulko kasvojeni eteen." Niin Absalom siirtyi omaan taloonsa eikä tullut kuninkaan kasvojen eteen.',
        25: 'Mutta koko Israelissa ei ollut yhtään niin komeaa miestä kuin Absalom, eikä ketään niin ylisteltyä. Kantapäästä kiireeseen asti hänessä ei ollut yhtään virhettä.',
        26: 'Kun hän ajatti hiuksensa – aina vuoden kuluttua hän ajatti ne, sillä ne tulivat hänelle niin raskaiksi, että hänen täytyi ne ajattaa – hänen hiuksensa painoivat kaksisataa sekeliä kuninkaan painoa.',
        27: 'Absalomille oli syntynyt kolme poikaa ja tytär, jonka nimi oli Taamar. Hän oli kaunis nainen.',
        28: 'Absalom asui kaksi vuotta Jerusalemissa tulematta kuninkaan kasvojen eteen.',
        29: 'Absalom lähetti sanan Jooabille lähettääkseen hänet kuninkaan luo, mutta tämä ei tahtonut tulla hänen luokseen. Hän lähetti vielä toisen kerran, mutta hän ei tahtonut tulla.',
        30: 'Hän sanoi palvelijoilleen: "Katsokaa, Jooabin maapalsta on maapalstani vieressä, ja hänellä on siinä ohraa. Menkää ja sytyttäkää se palamaan." Sitten Absalomin palvelijat sytyttivät maapalstan palamaan.',
        31: 'Jooab nousi ja meni Absalomin luo taloon ja sanoi hänelle: "Miksi palvelijasi ovat sytyttäneet palamaan maapalstan, joka on minun omani?"',
        32: 'Absalom vastasi Jooabille: "Katso, minä lähetin sinulle sanan: Tule tänne, lähetän sinut kuninkaan luo sanomaan: Mitä varten minä olen tullut kotiin Gesurista? Olisi parempi, jos vielä olisin siellä. Nyt minä tahdon nähdä kuninkaan kasvot, ja jos minussa on vääryys, surmatkoon hän minut."',
        33: 'Jooab meni kuninkaan luo ja kertoi hänelle tämän. Hän kutsui Absalomin, ja tämä tuli kuninkaan luo ja kumartui kasvoilleen maahan kuninkaan eteen, ja kuningas suuteli Absalomia.',
    },
    15: {
        1: 'Mutta sitten tapahtui, että Absalom hankki itselleen vaunut ja hevoset sekä viisikymmentä miestä, jotka juoksivat hänen edellään.',
        2: 'Absalomilla oli tapana asettua varhain aamulla sen tien viereen, joka vei portille, ja kun joku oli tulossa kuninkaan eteen saamaan oikeutta riita-asiassaan, Absalom kutsui hänet ja kysyi: "Mistä kaupungista olet?" Kun tämä vastasi: "Palvelijasi on siitä tai siitä Israelin sukukunnasta",',
        3: 'Absalom sanoi hänelle: "Asiasi on kyllä hyvä ja oikea, mutta kuninkaan luona ei ole ketään, joka sinua kuulisi."',
        4: 'Absalom sanoi vielä: "Jospa minut asetettaisiin tuomariksi maahan! Silloin tulisi minun eteeni jokainen, jolla on riita- tai oikeusasia, ja antaisin hänelle oikeuden."',
        5: 'Kun joku lähestyi kumartaakseen häntä, hän ojensi kätensä, tarttui häneen ja suuteli häntä.',
        6: 'Näin Absalom teki kaikille israelilaisille, jotka tulivat kuninkaan eteen saamaan oikeutta. Ja Absalom varasti Israelin miesten sydämet.',
        7: 'Neljän vuoden kuluttua Absalom sanoi kerran kuninkaalle: "Salli minun mennä Hebroniin täyttämään lupaus, jonka olen Herralle tehnyt.',
        8: 'Sillä asuessani Gesurissa, Aramissa, palvelijasi teki lupauksen ja sanoi: \'Jos Herra antaa minun tulla takaisin Jerusalemiin, palvelen Herraa.\'"',
        9: 'Kuningas sanoi hänelle: "Mene rauhassa." Hän nousi ja meni Hebroniin.',
        10: 'Mutta Absalom lähetti vakoojia kaikkiin Israelin sukukuntiin ja sanoi: "Kun kuulette torven äänen, sanokaa: \'Absalom on tullut kuninkaaksi Hebronissa.\'"',
        11: 'Absalomin kanssa oli Jerusalemista kutsuvieraina mennyt kaksisataa miestä, jotka menivät sinne aivan viattomina tietämättä koko asiasta mitään.',
        12: 'Absalom lähetti myös, sillä aikaa kun hän uhrasi teurasuhrejaan, noutamaan giilolaisen Ahitofelin, Daavidin neuvonantajan, hänen kaupungistaan Giilosta. Salaliitto vahvistui, ja yhä enemmän kansaa meni Absalomin puolelle.',
        13: 'Daavidin luo tultiin ilmoittamaan: "Israelin miesten sydämet ovat kääntyneet Absalomin puolelle."',
        14: 'Daavid sanoi kaikille palvelijoilleen, jotka olivat hänen luonaan Jerusalemissa: "Nouskaa, paetkaamme, sillä meillä ei ole muuta pelastusta Absalomin käsistä. Lähtekää nopeasti, ettei hän äkkiä saavuttaisi meitä ja saattaisi onnettomuutta meille ja surmaisi kaupungin asukkaita miekan terällä."',
        15: 'Kuninkaan palvelijat vastasivat kuninkaalle: "Tehtäköön aivan niin kuin herrani, kuningas, harkitsee parhaaksi. Me olemme palvelijoitasi."',
        16: 'Kuningas lähti jalkaisin, ja koko hänen hovinsa seurasi häntä. Kuitenkin kuningas jätti kymmenen sivuvaimoaan jäljelle vartioimaan linnaa.',
        17: 'Kuningas lähti, ja kaikki väki seurasi häntä. He pysähtyivät kaukaisimman talon kohdalle',
        18: 'kaikkien hänen palvelijoidensa kulkiessa hänen ohitseen. Myös kaikki kreetit ja pleetit sekä kaikki gatilaiset, kuusisataa miestä, jotka olivat tulleet hänen perässään Gatista, kulkivat kuninkaan ohi.',
        19: 'Kuningas sanoi gatilaiselle Ittaille: "Miksi sinäkin tulet kanssamme? Käänny takaisin ja jää kuninkaan luo, sillä sinä olet vieras, vieläpä maanpaossa kotoasi.',
        20: 'Eilen sinä tulit. Ottaisinko minä jo tänä päivänä sinut harhailemaan meidän kanssamme matkallemme, kun minä itsekin menen, minne menenkin? Käänny takaisin ja vie veljesi mukanasi. Armo ja uskollisuus sinulle!"',
        21: 'Mutta Ittai vastasi kuninkaalle ja sanoi: "Niin totta kuin Herra elää, ja niin totta kuin herrani, kuningas, elää: missä paikassa herrani kuningas on, siellä tahtoo myös palvelijasi olla, olkoonpa se elämäksi tai kuolemaksi."',
        22: 'Daavid sanoi Ittaille: "Tule sitten ja kulje ohitseni." Niin gatilainen Ittai kulki ohi ja kaikki hänen miehensä ja kaikki lapset, jotka olivat hänen kanssaan.',
        23: 'Koko maa itki suureen ääneen, kun kaikki väki kulki ohi. Kun kuningas oli kulkemassa Kidronin laakson poikki kaiken väen kulkiessa erämaan tielle päin,',
        24: 'katso, siinä oli myös Saadok sekä hänen kanssaan kaikki leeviläiset, jotka kantoivat Jumalan liitonarkkia. He laskivat Jumalan arkin maahan, ja Ebjatar uhrasi, kunnes kaikki väki kaupungista oli ehtinyt kulkea ohi.',
        25: 'Kuningas sanoi Saadokille: "Vie Jumalan arkki takaisin kaupunkiin. Jos löydän armon Herran silmien edessä, hän tuo minut takaisin ja antaa minun vielä nähdä hänet ja hänen asumuksensa.',
        26: 'Mutta jos hän sanoo näin: \'Minä en ole mieltynyt sinuun\', niin, katso, hän tehköön minulle, minkä hyväksi näkee."',
        27: 'Vielä kuningas sanoi pappi Saadokille: "Sinähän olet näkijä. Palaa rauhassa kaupunkiin, sinä ja sinun poikasi Ahimaas ja Ebjatarin poika Joonatan, molemmat poikanne, teidän kanssanne.',
        28: 'Katsokaa, minä viivyn kahlauspaikoissa erämaassa, kunnes teiltä tulee sana tiedokseni."',
        29: 'Saadok ja Ebjatar veivät Jumalan arkin takaisin Jerusalemiin ja jäivät sinne.',
        30: 'Daavid kulki itkien Öljymäkeä ylös, pää peitettynä ja paljain jaloin. Myös kaikki väki, mikä oli hänen kanssaan, oli peittänyt päänsä, ja he kulkivat itkien lakkaamatta.',
        31: 'Kun sitten Daavidille kerrottiin, että myös Ahitofel oli salaliittolaisten joukossa Absalomin puolella, Daavid sanoi: " Herra, käännä Ahitofelin neuvo hulluudeksi."',
        32: 'Kun sitten Daavid oli tullut vuoren laelle, jossa Jumalaa rukoiltiin, tuli arkilainen Huusai häntä vastaan viitta reväistynä ja multaa pään päällä.',
        33: 'Daavid sanoi hänelle: "Jos sinä tulet kanssani, olet minulle vain kuormaksi.',
        34: "Mutta jos palaat kaupunkiin ja sanot Absalomille: 'Minä tahdon olla palvelijasi, kuningas. Minä olen ennen ollut isäsi palvelija, mutta nyt tahdon olla sinun palvelijasi', voit olla minulle avuksi tekemällä Ahitofelin neuvon tyhjäksi.",
        35: 'Siellähän ovat kanssasi myös papit, Saadok ja Ebjatar. Kaikki, mitä kuulet kuninkaan linnasta, ilmoita papeille, Saadokille ja Ebjatarille.',
        36: 'Katso, heillä on siellä mukanaan myös molemmat poikansa, Saadokilla Ahimaas ja Ebjatarilla Joonatan. Näiden kautta voitte lähettää minulle tiedon kaikesta, mitä kuulette."',
        37: 'Huusai, Daavidin ystävä, meni kaupunkiin, juuri kun Absalom tuli Jerusalemiin.',
    },
    16: {
        1: 'Kun Daavid oli kulkenut vähän matkaa vuoren laelta, tuli häntä vastaan Siiba, Mefibosetin palvelija, mukanaan satuloitu aasipari, jonka selässä oli kaksisataa leipää, sata rusinakakkua, sata hedelmää ja leili viiniä.',
        2: 'Kuningas sanoi Siiballe: "Mitä sinä näillä teet?" Siiba vastasi: "Aasit ovat kuninkaan perheelle ratsastettaviksi, leipä ja hedelmät palvelijoille syötäviksi ja viini uupuneiden juotavaksi erämaassa."',
        3: 'Kuningas sanoi: "Mutta missä herrasi poika on?" Siiba vastasi kuninkaalle: "Hän jäi Jerusalemiin, sillä hän ajatteli: \'Nyt Israelin heimo antaa minulle takaisin isäni kuninkuuden.\'"',
        4: 'Kuningas sanoi Siiballe: "Katso, kaikki, mitä Mefibosetilla on, tulee omaksesi." Siiba vastasi: "Minä kumarran, suo minun löytää armo silmiesi edessä, herrani, kuningas."',
        5: 'Kun kuningas Daavid tuli Bahurimiin, katso, sieltä tuli mies, joka oli sukua Saulin perheelle, nimeltä Siimei, Geeran poika. Hän tuli ja kiroili tullessaan.',
        6: 'Hän viskeli kivillä Daavidia ja kaikkia kuningas Daavidin palvelijoita, vaikka kaikki väki ja kaikki sankarit olivat hänen oikealla ja vasemmalla puolellaan.',
        7: 'Kiroillessaan häntä Siimei sanoi näin: "Pois, pois, sinä murhamies, sinä kelvoton!',
        8: 'Herra kostaa sinulle kaiken Saulin perheen veren, hänen, jonka sijaan olet tullut kuninkaaksi. Herra antaa nyt kuninkuuden poikasi Absalomin käteen. Katso, sinä olet itse joutunut onnettomuuteen, sillä murhamies sinä olet."',
        9: 'Abisai, Serujan poika, sanoi kuninkaalle: "Miksi tuo koiranraato saa kiroilla herraani, kuningasta? Anna minun mennä ja lyödä häneltä pää poikki."',
        10: 'Mutta kuningas vastasi: "Mitä teillä on minun kanssani tekemistä, te Serujan pojat? Jos hän kiroilee ja jos Herra on käskenyt häntä: \'Kiroile Daavidia\', niin kuka voi sanoa: \'Miksi niin teet?\'"',
        11: 'Daavid sanoi vielä Abisaille ja kaikille palvelijoilleen: "Katso, oma poikani, joka on lähtenyt minun ruumiistani, väijyy henkeäni, miksi ei sitten tämä benjaminilainen? Antakaa hänen olla, kiroilkoon vain, sillä Herra on häntä käskenyt.',
        12: 'Ehkä Herra vielä näkee kurjuuteni, ja ehkä Herra maksaa minulle hyvällä hänen tämänpäiväisen kiroilunsa."',
        13: 'Daavid kulki miehineen tietä myöten, ja Siimei kulki pitkin vuoren rinnettä rinnan hänen kanssaan, kiroili kulkiessaan ja viskeli kiviä ja heitteli soraa.',
        14: 'Kun kuningas ja kaikki väki, joka oli hänen kanssaan, olivat tulleet sinne uupuneina, hän hengähti siellä.',
        15: 'Absalom ja kaikki kansa, Israelin miehet, olivat tulleet Jerusalemiin, ja Ahitofel oli hänen kanssaan.',
        16: 'Kun arkilainen Huusai, Daavidin ystävä, tuli Absalomin luo, Huusai sanoi Absalomille: "Eläköön kuningas! Eläköön kuningas!"',
        17: 'Absalom sanoi Huusaille: "Tällainenko on rakkautesi ystävääsi kohtaan? Miksi et mennyt ystäväsi kanssa?"',
        18: 'Huusai vastasi Absalomille: "Ei, vaan kenet Herra ja tämä kansa ja kaikki Israelin miehet ovat valinneet, sen puolella olen, ja sen luokse jään.',
        19: 'Myös toiseksi: ketä minä palvelisin? Enkö hänen poikaansa? Niin kuin olen palvellut isääsi, tahdon palvella sinuakin."',
        20: 'Absalom sanoi Ahitofelille: "Antakaa nyt neuvo, mitä meidän on tehtävä."',
        21: 'Ahitofel vastasi Absalomille: "Mene isäsi sivuvaimojen luo, jotka hän on jättänyt linnaa vartioimaan. Silloin koko Israel saa kuulla, että sinä olet saattanut itsesi isäsi vihoihin, ja kaikki, jotka ovat kanssasi, saavat rohkeutta."',
        22: 'Absalomille pystytettiin teltta katolle, ja Absalom meni isänsä sivuvaimojen luo koko Israelin nähden.',
        23: 'Ahitofelin antama neuvo oli siihen aikaan kuin Jumalalta saatu vastaus: sen arvoinen oli jokainen Ahitofelin neuvo sekä Daavidille että Absalomille.',
    },
    17: {
        1: 'Ahitofel sanoi Absalomille: "Salli minun valita kaksitoista tuhatta miestä ja nousta tänä yönä ajamaan takaa Daavidia,',
        2: 'niin karkaan hänen kimppuunsa, kun hän on väsynyt ja hänen kätensä ovat herpautuneet, ja saatan hänet kauhun valtaan, niin että kaikki väki, mitä hänen kanssaan on, pakenee, ja surmaan kuninkaan yksinään.',
        3: 'Sitten palautan kaiken kansan luoksesi. Kaikkien palaaminen riippuu siitä miehestä, jota sinä etsit. Kaikki kansa saa rauhan."',
        4: 'Tämä miellytti Absalomia ja kaikkia Israelin vanhimpia.',
        5: 'Kuitenkin Absalom sanoi: "Kutsukaa myös arkilainen Huusai kuullaksemme, mitä hänellä on sanottavana."',
        6: 'Kun Huusai tuli Absalomin luo, Absalom sanoi hänelle: "Niin ja niin puhui Ahitofel. Onko meidän tehtävä hänen sanansa mukaan? Jollei, puhu sinä."',
        7: 'Huusai vastasi Absalomille: "Ei ole hyvä se neuvo, jonka Ahitofel tällä kertaa on antanut."',
        8: 'Huusai sanoi vielä: "Sinä tiedät, että isäsi ja hänen miehensä ovat sankareita ja julmistuneita kuin karhu kedolla, jolta on poikaset riistetty. Myös isäsi on sotilas, joka ei lepää yöllä väen kanssa.',
        9: "Katso, hän on nyt piiloutunut johonkin onkaloon tai muuhun paikkaan. Jos jo alussa meikäläisiä kaatuisi ja se saataisiin kuulla, niin sanottaisiin: 'Väelle, joka seurasi Absalomia, on tullut tappio.'",
        10: 'Silloin urhoollisinkin, jolla on sydän kuin leijonalla, menettäisi rohkeutensa, sillä koko Israel tietää, että isäsi on sankari ja että ne, jotka ovat hänen kanssaan, ovat urhoollisia miehiä.',
        11: 'Sen tähden neuvoni on tämä: Koottakoon sinun luoksesi koko Israel Daanista aina Beersebaan asti, että niitä tulee niin paljon kuin hiekkaa meren rannalla. Lähde sinä itsekin taisteluun.',
        12: 'Kun karkaamme hänen kimppuunsa, missä ikinä hänet tavataan, painumme hänen päälleen, niin kuin kaste laskeutuu maahan. Eikä hänestä ja kaikista niistä miehistä, jotka ovat hänen kanssaan, jää jäljelle ainoatakaan.',
        13: 'Jos hän vetäytyisi johonkin kaupunkiin, niin koko Israel asettaisi köydet sen kaupungin ympärille, ja kiskoisimme sen alas laaksoon, kunnes siitä ei löytyisi kiveäkään."',
        14: 'Silloin Absalom ja kaikki Israelin miehet sanoivat: "Arkilaisen Huusain neuvo on parempi kuin Ahitofelin neuvo." Sillä Herra oli säätänyt sen näin tehdäkseen tyhjäksi Ahitofelin hyvän neuvon, että Herra saattaisi Absalomin onnettomuuteen.',
        15: 'Huusai sanoi papeille, Saadokille ja Ebjatarille: "Sen ja sen neuvon Ahitofel on antanut Absalomille ja Israelin vanhimmille, ja sen ja sen neuvon olen minä antanut.',
        16: 'Lähettäkää nyt pian ja ilmoittakaa Daavidille tämä sana: \'Älä jää yöksi kahluupaikkoihin erämaahan, vaan mene joen yli, ettei kuningas ja kaikki väki, joka on hänen kanssaan, joutuisi perikatoon.\'"',
        17: 'Joonatan ja Ahimaas olivat asettuneet Roogelin lähteelle, ja eräs palvelijatar kuljetti heille sinne sanaa. Sitten he menivät aina ja veivät sanan kuningas Daavidille. Sillä he eivät uskaltaneet näyttäytyä menemällä kaupunkiin.',
        18: 'Mutta eräs poikanen näki heidät ja ilmoitti Absalomille. Silloin he molemmat menivät kiireesti pois ja tulivat erään miehen taloon Bahurimiin. Hänellä oli kaivo pihallaan, ja he laskeutuivat siihen.',
        19: 'Hänen vaimonsa otti peitteen ja levitti sen kaivon suulle ja sirotti jyviä sen päälle, niin ettei voitu huomata mitään.',
        20: 'Kun Absalomin palvelijat tulivat vaimon luo taloon, he kysyivät: "Missä ovat Ahimaas ja Joonatan?" Vaimo vastasi heille: "Tuosta he menivät vesilätäkön yli." He etsivät, ja kun eivät heitä löytäneet, he palasivat takaisin Jerusalemiin.',
        21: 'Mutta heti kun he olivat menneet, nousivat toiset kaivosta, menivät ja veivät sanan kuningas Daavidille. He sanoivat Daavidille: "Nouskaa ja menkää joutuin veden yli, sillä sen ja sen neuvon on Ahitofel antanut teitä vastaan."',
        22: 'Silloin Daavid ja kaikki väki, mikä oli hänen kanssaan, nousi, ja he menivät Jordanin yli. Kun aamu valkeni, ei ollut ainoatakaan, joka ei olisi tullut Jordanin yli.',
        23: 'Mutta kun Ahitofel näki, ettei hänen neuvoaan noudatettu, hän satuloi aasinsa, nousi ja lähti kotiinsa omaan kaupunkiinsa. Kun hän oli toimittanut talonsa, hän hirttäytyi. Hän kuoli, ja hänet haudattiin isänsä hautaan.',
        24: 'Daavid oli tullut Mahanaimiin, kun Absalom ja kaikki Israelin miehet hänen kanssaan menivät Jordanin yli.',
        25: 'Mutta Absalom oli asettanut Amasan Jooabin sijaan sotajoukon ylipäälliköksi. Amasa oli Jitra-nimisen israelilaisen miehen poika. Tämä mies oli yhtynyt Abigailiin, Naahaan tyttäreen, Jooabin äidin Serujan sisareen.',
        26: 'Israel ja Absalom leiriytyivät Gileadin maahan.',
        27: 'Kun Daavid tuli Mahanaimiin, niin Soobi, Naahaan poika, ammonilaisten Rabbasta, ja Maakir, Ammielin poika, Loodebarista, ja gileadilainen Barsillai, Roogelimista,',
        28: 'toivat sinne vuoteita, vateja ja saviastioita, vehnänjyviä, ohria, jauhoja ja paahdettuja jyviä, papuja, herneitä',
        29: 'sekä hunajaa, voita, lampaita ja juustoja ruuaksi Daavidille ja väelle, mikä oli hänen kanssaan, sillä he ajattelivat: "Väki on nälissään, uuvuksissa ja janoissaan erämaassa."',
    },
    18: {
        1: 'Daavid piti katselmuksen mukanaan olevalle väelle, ja asetti sille tuhannen- ja sadanpäämiehet.',
        2: 'Daavid lähetti väen liikkeelle: yhden kolmanneksen Jooabin johdolla, toisen kolmanneksen Abisain, Serujan pojan, Jooabin veljen, johdolla ja kolmannen kolmanneksen gatilaisen Ittain johdolla. Kuningas sanoi kansalle: "Minä lähden myös itse teidän kanssanne."',
        3: 'Mutta kansa vastasi: "Älä lähde. Sillä jos me pakenemme, meistä ei välitetä, ja jos puolet meistä saa surmansa, meistä ei silloinkaan välitetä, mutta sinä olet kuin kymmenen tuhatta meistä. Sen tähden on nyt parempi, että sinä olet valmiina tulemaan meille avuksi kaupungista."',
        4: 'Niin kuningas sanoi heille: "Minä teen, minkä hyväksi näette." Kuningas asettui portin pieleen, mutta kaikki väki lähti liikkeelle sadan ja tuhannen joukkoina.',
        5: 'Kuningas käski myös Jooabia, Abisaita ja Ittaita ja sanoi: "Pidelkää minulle mieliksi hellävaroin nuorukaista Absalomia." Kaikki kansa kuuli, kuinka kuningas antoi kaikille päälliköille käskyn Absalomista.',
        6: 'Väki lähti kentälle Israelia vastaan, ja taistelu tapahtui Efraimin metsässä.',
        7: 'Siellä Daavidin palvelijat voittivat Israelin väen, ja siellä oli sinä päivänä suuri mieshukka: kaksikymmentä tuhatta miestä.',
        8: 'Taistelu levisi koko siihen seutuun, ja metsä söi sinä päivänä enemmän väkeä kuin miekka.',
        9: 'Absalom osui yhteen Daavidin palvelijain kanssa. Absalom ratsasti muulilla, ja kun muuli tuli suuren, tiheäoksaisen tammen alle, hän tarttui päästään tammeen, niin että hän jäi riippumaan taivaan ja maan välille, kun muuli juoksi pois hänen altaan.',
        10: 'Sen näki eräs mies ja ilmoitti sen Jooabille ja sanoi: "Katso, minä näin Absalomin riippuvan tammessa."',
        11: 'Niin Jooab sanoi miehelle, joka ilmoitti hänelle tämän: "Jos näit sen, miksi et lyönyt häntä siinä maahan? Minun olisi ollut annettava sinulle kymmenen hopeasekeliä ja vyö."',
        12: 'Mutta mies vastasi Jooabille: "Vaikka käsiini punnittaisiin tuhat hopeasekeliä, en sittenkään kävisi käsiksi kuninkaan poikaan, sillä kuningas käski meidän kuultemme sinua, Abisaita ja Ittaita sanoen: \'Pitäkää vaari nuorukaisesta, Absalomista.\'',
        13: 'Vai kavaltaisinko minä oman henkeni? Sillä eihän mikään pysy salassa kuninkaalta, ja sinä pysyisit kyllä syrjässä."',
        14: 'Niin Jooab sanoi: "Minä en enää kuluta aikaa kanssasi." Hän otti kolme keihästä käteensä ja pisti ne Absalomin rintaan, kun hän vielä eli tammessa.',
        15: 'Kymmenen nuorta miestä, Jooabin aseenkantajaa, astui Absalomin luo, ja he löivät hänet kuoliaaksi.',
        16: 'Jooab puhalsi torveen, ja väki palasi ajamasta takaa Israelia, kun Jooab pysäytti väen.',
        17: 'He ottivat Absalomin ja heittivät hänet metsässä suureen kuoppaan ja pystyttivät sangen suuren kivikasan hänen päälleen. Mutta koko Israel pakeni, kukin teltalleen.',
        18: 'Absalom oli eläessään hankkinut ja pystyttänyt itselleen patsaan, joka on Kuninkaanlaaksossa, sillä hän sanoi: "Minulla ei ole poikaa, joka säilyttäisi nimeni muiston." Patsaan hän oli kutsunut nimensä mukaan, ja sen nimi on vielä tänäkin päivänä Absalomin muistomerkki.',
        19: 'Ahimaas, Saadokin poika, sanoi: "Juoksen saattamaan kuninkaalle ilosanoman, että Herra on auttanut hänet hänen vihollistensa käsistä oikeuteensa."',
        20: 'Mutta Jooab sanoi hänelle: "Tänä päivänä et ole ilosanoman viejä. Jonakin muuna päivänä vienet ilosanoman, mutta tänä päivänä et vie ilosanomaa, sillä onhan kuninkaan poika kuollut."',
        21: 'Sitten Jooab sanoi eräälle kuusilaiselle: "Mene ja ilmoita kuninkaalle, mitä olet nähnyt." Niin kuusilainen kumarsi Jooabille ja lähti juoksemaan.',
        22: 'Mutta Ahimaas, Saadokin poika, sanoi taas Jooabille: "Tulkoon mitä tahansa, mutta minäkin juoksen kuusilaisen jälkeen." Jooab sanoi: "Miksi sinä juoksisit, poikani, eihän sinulle siitä ilosanoman saattajan palkkaa tule?"',
        23: '"Tulkoon mitä tahansa, mutta juoksen." Silloin hän sanoi hänelle: "Juokse sitten." Ahimaas lähti juoksemaan Lakeuden tietä ja sivuutti kuusilaisen.',
        24: 'Daavid istui molempien porttien välissä. Tähystäjä meni portin katolle muurin päälle. Kun hän nosti silmänsä ja katseli, katso: mies tuli juosten yksinään.',
        25: 'Tähystäjä huusi ja ilmoitti sen kuninkaalle. Kuningas sanoi: "Jos hän on yksin, hänellä on ilosanoma." Hän tuli yhä lähemmäksi.',
        26: 'Tähystäjä näki toisen miehen tulevan juosten, ja hän huusi porttiin sanoen: "Minä näen vielä toisenkin miehen tulevan ja hän juoksee yksin." Kuningas sanoi: "Sekin tuo ilosanomaa."',
        27: 'Sitten tähystäjä sanoi: "Ensimmäisen juoksu näyttää minusta Ahimaasin, Saadokin pojan, juoksulta." Kuningas sanoi: "Hän on hyvä mies. Hän tulee hyviä sanomia tuoden."',
        28: 'Ahimaas huusi ja sanoi kuninkaalle: "Rauha!" Hän kumartui kasvoilleen maahan kuninkaan eteen ja sanoi: "Kiitetty olkoon Herra, Jumalasi, joka on antanut käsiisi ne miehet, jotka nostivat kätensä herraani, kuningasta, vastaan."',
        29: 'Kuningas kysyi: "Voiko nuorukainen Absalom hyvin?" Ahimaas vastasi: "Minä näin suuren väkijoukon, kun kuninkaan palvelija Jooab lähetti minut, palvelijasi, mutta en tiedä, mitä se oli."',
        30: 'Kuningas sanoi: "Astu syrjään ja asetu sinne." Hän astui syrjään ja jäi seisomaan sinne.',
        31: 'Katso, sitten kuusilainen tuli perille, ja kuusilainen sanoi: "Ilosanoma herralleni, kuninkaalle: Herra on tänä päivänä auttanut sinut oikeuteesi kaikkien niiden käsistä, jotka ovat nousseet sinua vastaan."',
        32: 'Kuningas kysyi kuusilaiselta: "Voiko nuorukainen Absalom hyvin?" Kuusilainen vastasi: "Käyköön herrani kuninkaan vihollisille ja kaikille, jotka nousevat sinua vastaan tehdäkseen sinulle pahaa, niin kuin on käynyt sille nuorukaiselle."',
    },
    19: {
        1: 'Kuningas tuli kovin järkytetyksi, nousi portin päällä olevaan yläsaliin ja itki. Mennessään hän huusi näin: "Poikani Absalom, minun poikani, oma poikani Absalom! Jospa minä olisin kuollut sinun sijastasi! Absalom, poikani, oma poikani!"',
        2: 'Jooabille ilmoitettiin: "Katso, kuningas itkee ja suree Absalomia."',
        3: 'Voitto muuttui sinä päivänä suruksi kaikelle kansalle, koska kansa sinä päivänä kuuli sanottavan, että kuningas oli murheissaan poikansa tähden.',
        4: 'Kansa tuli kaupunkiin kuin varkain sinä päivänä, niin kuin tulee varkain väki, joka on häväissyt itsensä pakenemalla taistelusta.',
        5: 'Kuningas oli peittänyt kasvonsa, ja hän huusi kovalla äänellä: "Poikani Absalom! Absalom, poikani, oma poikani!"',
        6: 'Jooab meni sisälle kuninkaan luo ja sanoi: "Sinä olet tänä päivänä nostanut häpeän kaikkien palvelijoittesi kasvoille, vaikka he tänä päivänä ovat pelastaneet sekä oman henkesi että poikiesi, tyttäriesi, vaimojesi ja sivuvaimojesi hengen.',
        7: 'Rakastathan niitä, jotka vihaavat sinua, ja vihaat niitä, jotka rakastavat sinua. Sillä olet tänään antanut tietää, ettei sinulla olekaan päälliköitä eikä palvelijoita, – niin, nyt tiedän, että jos Absalom olisi elossa ja me kaikki olisimme tänään kuolleet, se olisi sinulle mieleen.',
        8: 'Mutta nouse nyt ylös ja mene ulos ja puhuttele ystävällisesti palvelijoitasi. Sillä vannon Herran kautta: jollet mene ulos, niin totisesti yhtään ainoatakaan miestä ei jää luoksesi tänä yönä. Niin tämä on oleva sinulle suurempi onnettomuus kuin mikään muu, joka on kohdannut sinua nuoruudestasi tähän päivään saakka."',
        9: 'Kuningas nousi ja asettui istumaan porttiin, ja kaikelle kansalle ilmoitettiin ja sanottiin: "Kuningas istuu nyt portissa." Kaikki kansa tuli kuninkaan eteen. Mutta kun Israel oli paennut, kukin telttamajalleen,',
        10: 'alkoi kaikki kansa kaikkien Israelin heimojen keskuudessa riidellä ja sanoa: "Kuningas on pelastanut meidät vihollistemme kourista, hän on vapauttanut meidät filistealaisten kourista, ja nyt hän on Absalomia paossa, maasta poissa.',
        11: 'Mutta Absalom, jonka me olemme voidelleet kuninkaaksemme, on kuollut taistelussa. Miksi ette nyt ryhdy tuomaan kuningasta takaisin?"',
        12: 'Kuningas Daavid lähetti sanan papeille Saadokille ja Ebjatarille ja käski sanoa: "Puhukaa Juudan vanhimmille ja sanokaa: \'Miksi te olette viimeiset tuomaan kuningasta takaisin hänen linnaansa? Sillä se, mitä koko Israel puhuu, on tullut kuninkaan tietoon hänen olinpaikkaansa.',
        13: "Te olette veljiäni, luutani ja lihaani. Miksi te olisitte viimeiset tuomaan kuningasta takaisin?'",
        14: 'Amasalle sanokaa: \'Olethan sinä luutani ja lihaani. Jumala rangaiskoon minua nyt ja vasta, jollet sinä koko elinaikaasi ole sotapäällikköni Jooabin sijassa.\'"',
        15: 'Hän taivutti kaikkien Juudan miesten sydämet, niin että he yhtenä miehenä lähettivät sanomaan kuninkaalle: "Palaa takaisin, sinä ja kaikki palvelijasi."',
        16: 'Kuningas palasi takaisin ja tuli Jordanille. Juuda oli tullut Gilgaliin mennäkseen kuningasta vastaan ja tuodakseen kuninkaan Jordanin yli.',
        17: 'Myös Siimei, Geeran poika, benjaminilainen Bahurimista, lähti kiireellä Juudan miesten kanssa kuningas Daavidia vastaan.',
        18: 'Hänen kanssaan oli tuhat miestä Benjaminista sekä Siiba, Saulin perheen palvelija, viidentoista poikansa ja kahdenkymmenen palvelijansa kanssa. Nämä olivat rientäneet Jordanille ennen kuningasta',
        19: 'ja menneet kahluupaikasta yli noutamaan kuninkaan perheen ja toimittamaan, mitä hän näkisi hyväksi määrätä. Mutta Siimei, Geeran poika, heittäytyi kuninkaan eteen, kun hän oli lähtemässä Jordanin yli,',
        20: 'ja sanoi kuninkaalle: "Älköön herrani lukeko minulle pahaa tekoani älköönkä muistelko, kuinka väärin palvelijasi teki sinä päivänä, jona herrani, kuningas, lähti Jerusalemista. Älköön kuningas panko sitä sydämelleen.',
        21: 'Sillä palvelijasi tuntee, että minä olen tehnyt synnin. Sen tähden olen tänä päivänä ensimmäisenä koko Joosefin heimosta tullut tänne herraani, kuningasta, vastaan."',
        22: 'Abisai, Serujan poika, puuttui puheeseen ja sanoi: "Eikö Siimeitä ole rangaistava kuolemalla siitä, että hän on kiroillut Herran voideltua?"',
        23: 'Daavid vastasi: "Mitä teillä on tekemistä kanssani, te Serujan pojat, kun tulette minulle tänä päivänä kiusaajaksi? Olisiko ketään Israelissa tänä päivänä kuolemalla rangaistava? Minä tiedän tulleeni tänä päivänä Israelin kuninkaaksi."',
        24: 'Kuningas sanoi Siimeille: "Sinä et kuole", ja kuningas vannoi sen hänelle.',
        25: 'Mefiboset, Saulin pojanpoika, oli myös tullut kuningasta vastaan. Hän ei ollut pessyt jalkojaan, ei siistinyt partaansa eikä pesettänyt vaatteitaan siitä päivästä, jona kuningas lähti, siihen päivään asti, jona hän rauhassa tuli takaisin.',
        26: 'Kun hän nyt tuli Jerusalemista kuningasta vastaan, kuningas sanoi hänelle: "Miksi sinä et tullut kanssani, Mefiboset?"',
        27: 'Hän vastasi: "Herrani, kuningas, palvelijani petti minut. Sillä palvelijasi sanoi hänelle: \'Satuloi aasini ratsastaakseni sillä ja mennäkseni kuninkaan kanssa\' – sillä palvelijasihan on ontuva –',
        28: 'mutta hän on panetellut palvelijaasi herralle kuninkaalle. Herrani, kuningas, on kuitenkin kuin Jumalan enkeli. Tee siis, mitä hyväksi näet.',
        29: 'Sillä koko isäni suku oli herrani, kuninkaan, edessä kuoleman oma, ja kuitenkin sinä asetit palvelijasi niiden joukkoon, jotka syövät pöydässäsi. Mitäpä minulla on enää muuta oikeutta ja mitä valittamista kuninkaalle?"',
        30: 'Kuningas sanoi hänelle: "Mitäpä tuosta enää puhut? Minä olen sanonut, että sinä ja Siiba saatte jakaa keskenänne maaomaisuuden."',
        31: 'Mefiboset sanoi kuninkaalle: "Ottakoon hän sen vaikka kokonaan, kun kerran herrani, kuningas, on palannut rauhassa kotiinsa."',
        32: 'Gileadilainen Barsillai oli myös tullut Roogelimista ja meni kuninkaan kanssa Jordanille saattamaan häntä Jordanin yli.',
        33: 'Barsillai oli hyvin vanha, kahdeksankymmenen vuoden vanha. Hän oli elättänyt kuningasta tämän ollessa Mahanaimissa, sillä hän oli hyvin rikas mies.',
        34: 'Kuningas sanoi nyt Barsillaille: "Tule sinä mukaani, niin elätän sinut luonani Jerusalemissa."',
        35: 'Mutta Barsillai vastasi kuninkaalle: "Montako ikävuotta minulla enää lienee, että menisin kuninkaan kanssa Jerusalemiin:',
        36: 'Minä olen nyt kahdeksankymmenen vuoden vanha. Osaisinko minä enää erottaa hyvää pahasta, tai maistuisiko palvelijastasi miltään se, mitä hän syö ja mitä juo? Tai kuulostaisiko minusta enää miltään laulajien ja laulajattarien laulu? Miksi palvelijasi vielä tulisi kuormaksi herralleni, kuninkaalle?',
        37: 'Ainoastaan vähän matkaa seuraa palvelijasi kuningasta tuolle puolelle Jordanin. Miksi kuningas antaisi minulle sellaisen korvauksen?',
        38: 'Salli palvelijasi palata takaisin saadakseni kuolla omassa kaupungissani isäni ja äitini haudan ääressä. Mutta katso, tässä on palvelijasi Kimham, menköön hän Herrani, kuninkaan, kanssa. Tee hänelle, mitä hyväksi näet."',
        39: 'Niin kuningas sanoi: "Kimham tulkoon kanssani, ja minä teen hänelle, mitä hyväksi näet, ja kaiken, mitä sinä minulta toivot, teen sinulle."',
        40: 'Kaikki kansa meni Jordanin yli, ja kuningas itsekin meni. Kuningas suuteli Barsillaita ja hyvästeli hänet. Tämä palasi takaisin kotiinsa.',
        41: 'Kuningas meni Gilgaliin, ja Kimham meni hänen mukanaan, samoin myös kaikki Juudan kansa. He ja puolet Israelin kansasta veivät kuninkaan sinne yli.',
        42: 'Katso, silloin kaikki muut Israelin miehet tulivat kuninkaan luo ja sanoivat kuninkaalle: "Miksi meidän veljemme, Juudan miehet, ovat varkain tuoneet kuninkaan ja hänen perheensä sekä kaikki Daavidin miehet hänen kanssaan Jordanin yli?"',
        43: 'Mutta kaikki Juudan miehet vastasivat Israelin miehille: "Onhan kuningas meille läheisempi. Miksi vihastut siitä? Olemmeko me syöneet kuningasta, tai olemmeko vieneet hänet itsellemme?"',
        44: 'Israelin miehet vastasivat Juudan miehille ja sanoivat: "Minulla on kymmenen kertaa suurempi osa kuninkaaseen, myös Daavidiin, kuin sinulla. Miksi siis olet katsonut minut ylen? Enkö minä ensin puhunut kuninkaani takaisin tuomisesta?" Mutta Juudan miesten sanat olivat vielä ankarammat kuin Israelin miesten sanat.',
    },
    20: {
        1: 'Siellä oli sattumalta kelvoton mies, nimeltä Seba, Bikrin poika, benjaminilainen. Hän puhalsi torveen ja sanoi: "Meillä ei ole mitään osaa Daavidiin eikä perintöosaa Iisain poikaan. Kukin teltalleen, Israel!"',
        2: 'Silloin kaikki Israelin miehet luopuivat Daavidista ja seurasivat Sebaa, Bikrin poikaa, mutta Juudan miehet riippuivat kiinni kuninkaassaan ja seurasivat häntä Jordanilta aina Jerusalemiin.',
        3: 'Daavid tuli linnaansa Jerusalemiin. Kuningas otti ne kymmenen sivuvaimoa, jotka hän oli jättänyt palatsia vartioimaan, ja pani heidät vartioituun taloon. Hän elätti heitä, mutta ei mennyt heidän luokseen. Siellä he olivat eristettyinä kuolinpäiväänsä asti, elävän miehen leskinä.',
        4: 'Kuningas sanoi Amasalle: "Kutsu koolle Juudan miehet kolmen päivän kuluessa ja ole silloin itse paikallasi täällä."',
        5: 'Amasa meni kutsumaan koolle Juudaa, mutta hän viipyi yli sen ajan, jonka hän oli määrännyt.',
        6: 'Silloin Daavid sanoi Abisaille: "Nyt Seba, Bikrin poika, tekee meille enemmän pahaa kuin Absalom. Ota sinä herrasi palvelijat ja aja häntä takaa, ettei hän saisi haltuunsa varustettuja kaupunkeja ja repisi meiltä silmiä."',
        7: 'Jooabin miehet sekä kreetit ja pleetit ja kaikki valiosotilaat lähtivät liikkeelle hänen jäljessään. He lähtivät Jerusalemista ajamaan takaa Sebaa, Bikrin poikaa.',
        8: 'Mutta kun he olivat suuren kiven luona, joka on Gibeonissa, tuli Amasa heitä vastaan. Jooab oli puettu takkiinsa, ja sen päällä oli miekkavyö vyötäisille kiinnitettynä. Miekka oli tupessaan, mutta kun hän lähti liikkeelle, niin se putosi.',
        9: 'Silloin Jooab sanoi Amasalle: "Voitko hyvin, veljeni?" Jooab tarttui oikealla kädellään Amasaa partaan muka suudellakseen häntä.',
        10: 'Kun Amasa ei varonut miekkaa, joka Jooabilla oli kädessään, tämä pisti häntä sillä vatsaan, niin että hänen sisälmyksensä valuivat maahan. Toista pistoa ei tarvittu: hän kuoli. Jooab ja hänen veljensä Abisai ajoivat takaa Sebaa, Bikrin poikaa.',
        11: 'Mutta eräs Jooabin palvelijoista jäi seisomaan Amasan ääreen ja huusi: "Jokainen, joka on Jooabille myötämielinen ja joka on Daavidin puolella, seuratkoon Jooabia!"',
        12: 'Amasa virui verissään keskellä tietä. Mutta kun mies näki, että kaikki väki pysähtyi siihen, hän vei Amasan tieltä syrjään pellolle ja heitti vaatteen hänen päälleen nähdessään, että kaikki ohikulkijat pysähtyivät.',
        13: 'Kun hänet oli toimitettu pois tieltä, kulkivat kaikki ohi ja seurasivat Jooabia ajaakseen takaa Sebaa, Bikrin poikaa.',
        14: 'Tämä kulki kaikkien Israelin sukukuntien kautta Aabeliin ja Beet-Maakaan, ja kaikki beeriläiset kokoontuivat ja seurasivat häntä sinne asti.',
        15: 'He tulivat ja piirittivät häntä Aabel-Beet-Maakassa ja loivat kaupunkia vastaan vallin, joka ulottui ulkomuuriin. Kaikki Jooabin väki teki hävitystyötä kukistaakseen muurin.',
        16: 'Silloin eräs viisas nainen huusi kaupungista: "Kuulkaa! Kuulkaa! Sanokaa Jooabille, että hän tulee tänne lähelle puhutellakseni häntä."',
        17: 'Kun tämä tuli häntä lähelle, nainen sanoi: "Oletko Jooab?" Hän vastasi: "Olen." Nainen sanoi hänelle: "Kuule palvelijattaresi sanoja." Hän vastasi: "Minä kuulen."',
        18: 'Silloin nainen sanoi: "Muinoin oli tapana sanoa: \'On kysyttävä neuvoa Aabelista\', ja niin tuli valmista.',
        19: 'Minä olen rauhallisimpia ja uskollisimpia Israelissa, ja sinä koetat ottaa hengen kaupungilta, joka on äiti Israelissa. Miksi sinä tahdot hävittää Herran perintöosan?"',
        20: 'Jooab vastasi ja sanoi: "Pois se, pois se! En tahdo hävittää enkä tuhota.',
        21: 'Niin ei ole asia, vaan eräs mies Efraimin vuoristosta, nimeltä Seba, Bikrin poika, on nostanut kätensä kuningas Daavidia vastaan. Luovuttakaa hänet yksin, niin lähden pois kaupungin edustalta." Nainen vastasi Jooabille: "Katso, hänen päänsä heitetään sinulle muurin yli."',
        22: 'Sitten nainen viisaudessaan meni kaiken kansan luo. He löivät Sebalta, Bikrin pojalta, pään poikki ja heittivät sen Jooabille. Silloin tämä puhalsi torveen, ja he hajaantuivat kaupungin edustalta, kukin teltalleen. Mutta Jooab palasi kuninkaan luo Jerusalemiin.',
        23: 'Jooab oli Israelin koko sotajoukon ylipäällikkönä, ja Benaja, Joojadan poika, oli kreettien ja pleettien päällikkönä.',
        24: 'Adoram oli verotöiden valvojana, ja Joosafat, Ahiludin poika, oli kanslerina.',
        25: 'Seja oli kirjurina, ja Saadok ja Ebjatar olivat pappeina.',
        26: 'Myös jaairilainen Iira oli Daavidilla pappina.',
    },
    21: {
        1: 'Daavidin aikana oli nälänhätä, jota kesti kolme vuotta peräkkäin. Silloin Daavid etsi Herran kasvoja. Herra vastasi: "Saulin tähden, verivelan alaisen suvun tähden, koska hän surmasi gibeonilaisia."',
        2: 'Kuningas kutsui gibeonilaiset ja puhutteli heitä. Gibeonilaiset eivät olleet israelilaisia, vaan amorilaisten jäljelle jääneitä, ja israelilaiset olivat vannoneet heille valan, mutta Saul oli kiivaillessaan israelilaisten ja Juudan puolesta koettanut hävittää heidät.',
        3: 'Daavid sanoi gibeonilaisille: "Mitä minun on tehtävä hyväksenne, ja millä minun on sovitettava teidät, että siunaisitte Herran perintöosaa?"',
        4: 'Gibeonilaiset vastasivat hänelle: "Ei ole meidän ja Saulin sekä hänen sukunsa välillä kysymys hopeasta eikä kullasta, eikä meillä ole valtaa surmata ketään Israelissa." Hän sanoi: "Mitä sitten vaaditte minua tekemään hyväksenne?"',
        5: 'He vastasivat kuninkaalle: "Sen miehen, joka tahtoi meidät lopettaa ja joka aikoi hävittää meidät, niin ettei meillä olisi missä olla koko Israelin alueella,',
        6: 'sen miehen jälkeläisistä luovutettakoon meille seitsemän miestä lävistääksemme heidät paaluihin Herralle Saulin, Herran valitun, Gibeassa." Kuningas sanoi: "Minä luovutan."',
        7: 'Mefibosetin, Saulin pojan Joonatanin pojan, kuningas kuitenkin säästi Herran valan tähden, joka oli heidän välillään, Daavidin ja Joonatanin, Saulin pojan, välillä.',
        8: 'Kuningas otti Rispan, Aijan tyttären, kaksi poikaa, Armonin ja Mefibosetin, jotka tämä oli synnyttänyt Saulille, sekä Meerabin, Saulin tyttären, viisi poikaa, jotka tämä oli synnyttänyt Adrielille, meholalaisen Barsillain pojalle,',
        9: 'ja luovutti heidät gibeonilaisten käsiin. Nämä teloittivat heidät vuorella Herran edessä, niin että ne seitsemän sortuivat kaikki yhdessä. Näin heidät surmattiin elonleikkuun ensimmäisinä päivinä, ohranleikkuun alussa.',
        10: 'Silloin Rispa, Aijan tytär, otti säkin ja levitti sen kalliolle, ja se oli hänen vuoteenaan elonleikkuun alusta siihen asti, kunnes sade taivaasta vuoti heidän päälleen, eikä hän sallinut taivaan lintujen päivällä eikä metsän eläinten yöllä tulla heidän päälleen.',
        11: 'Kun Daavidille kerrottiin, mitä Rispa, Aijan tytär, Saulin sivuvaimo, oli tehnyt,',
        12: 'Daavid lähti ja otti Saulin ja hänen poikansa Joonatanin luut Gileadin Jaabeksen miehiltä, jotka olivat varkain ottaneet ne siltä torilta Beet-Seanista, jolle filistealaiset olivat heidät ripustaneet silloin, kun filistealaiset surmasivat Saulin Gilboassa.',
        13: 'Hän toi sieltä Saulin ja hänen poikansa Joonatanin luut. Myös teloitettujen luut koottiin',
        14: 'ja haudattiin yhdessä Saulin ja hänen poikansa Joonatanin luiden kanssa Benjaminin maahan Seelaan, Saulin isän, Kiisin, hautaan. Tehtiin kaikki, mitä kuningas oli käskenyt. Sen jälkeen Jumala armahti maata.',
        15: 'Taas syttyi sota filistealaisten ja Israelin välillä. Daavid lähti palvelijoineen sotimaan filistealaisia vastaan, ja Daavid väsyi.',
        16: 'Jisbi-Benob, Raafan jälkeläisiä, jonka keihäs painoi kolmesataa sekeliä vaskea ja joka oli puettu uusiin varusteisiin, aikoi surmata Daavidin.',
        17: 'Mutta Abisai, Serujan poika, tuli hänen avukseen ja löi filistealaisen kuoliaaksi. Daavidin miehet vannottivat hänellä valan sanoen: "Sinä et saa enää lähteä kanssamme taisteluun, ettet sammuttaisi Israelin lamppua."',
        18: 'Sen jälkeen oli taas taistelu filistealaisten kanssa Goobissa: silloin huusailainen Sibbekai surmasi Safin, joka myös oli Raafan jälkeläisiä.',
        19: 'Taas oli taistelu filistealaisia vastaan Goobissa, Elhanan, Jare-Ooregimin poika, beetlehemiläinen, surmasi gatilaisen Goljatin, jonka peitsen varsi oli kuin kangastukki.',
        20: 'Taas oli taistelu Gatissa. Siellä oli kookas mies, jolla oli kuusi sormea kummassakin kädessä ja kuusi varvasta kummassakin jalassa, yhteensä kaksikymmentä neljä. Hänkin polveutui Raafasta.',
        21: 'Kun hän häpäisi Israelia, surmasi hänet Joonatan, Daavidin veljen Simean poika.',
        22: 'Nämä neljä polveutuivat gatilaisesta Raafasta. He kaatuivat Daavidin ja hänen palvelijoidensa käden kautta.',
    },
    22: {
        1: 'Daavid puhui Herralle tämän laulun sanat sinä päivänä, jona Herra oli pelastanut hänet kaikkien hänen vihollistensa ja Saulin vallasta. Hän sanoi:',
        2: '" Herra, kallioni, linnani ja pelastajani!',
        3: 'Jumala, vuoreni, jonka turviin pakenen, kilpeni, autuuteni sarvi, varustukseni ja pakopaikkani, pelastajani, joka pelastat minut väkivallasta!',
        4: "'Ylistetty olkoon Herra ' – niin minä huudan, ja pelastun vihollisistani.",
        5: 'Sillä kuoleman aallot piirittivät minut, turmion virrat pelästyttivät minut.',
        6: 'Helvetin paulat kietoivat minut, kuoleman ansat yllättivät minut.',
        7: 'Ahdistuksessani huusin Herraa, huusin Jumalaani. Hän kuuli ääneni temppelistään, huutoni kohosi hänen korviinsa.',
        8: 'Maa huojui ja järisi, taivaan perustukset järkkyivät. Ne horjuivat, sillä hänen vihansa syttyi.',
        9: 'Savu suitsusi hänen sieraimistaan, kuluttava tuli hänen suustaan, palavat hiilet hehkuivat hänestä.',
        10: 'Hän notkisti taivaan ja astui alas, synkkä pilvi jalkojensa alla.',
        11: 'Hän ajoi kerubin kannattamana ja lensi, hän näkyi tuulen siipien päältä.',
        12: 'Hän pani pimeyden majaksi ympärilleen, synkät vedet, paksut pilvet.',
        13: 'Hohteesta, joka kävi hänen edellään, hehkuivat palavat hiilet.',
        14: 'Herra jyrisi taivaasta, Korkein antoi äänensä kaikua.',
        15: 'Hän lennätti nuolia ja hajotti heidät, salamoita, ja kauhistutti heidät.',
        16: 'Meren syvyydet tulivat näkyviin, maanpiirin perustukset paljastuivat Herran nuhtelusta, hänen vihansa hengen puuskasta.',
        17: 'Hän ojensi kätensä korkeudesta ja tarttui minuun, veti minut ylös suurista vesistä.',
        18: 'Hän pelasti minut voimallisesta vihollisestani, vihamiehistäni, sillä he olivat minua väkevämmät.',
        19: 'He hyökkäsivät kimppuuni hätäni päivänä, mutta Herra tuli tuekseni.',
        20: 'Hän toi minut avaraan paikkaan, hän vapautti minut, sillä hän oli minuun mieltynyt.',
        21: 'Herra tekee minulle vanhurskauteni mukaan. Kätteni puhtauden mukaan hän minulle maksaa.',
        22: 'Sillä minä noudatan Herran teitä enkä luovu Jumalastani jumalattomuuteen.',
        23: 'Kaikki hänen oikeutensa ovat silmieni edessä, enkä poikkea hänen käskyistään.',
        24: 'Olen vilpitön häntä kohtaan ja varon itseni pahoista teoista.',
        25: 'Sen tähden Herra palkitsee minulle vanhurskauteni mukaan, sen mukaan kuin olen puhdas hänen silmiensä edessä.',
        26: 'Hurskasta kohtaan olet hurskas, nuhteetonta sankaria kohtaan nuhteeton,',
        27: 'puhdasta kohtaan olet puhdas, mutta kieroa kohtaan nurja.',
        28: 'Pelastat nöyrän kansan, mutta silmäsi ovat ylpeitä vastaan, sinä alennat heidät.',
        29: 'Sillä sinä, Herra, olet lamppuni. Herra valaisee pimeyteni.',
        30: 'Avullasi hyökkään rosvojoukkoa vastaan. Jumalani avulla ryntään muurin yli.',
        31: 'Jumalan tie on nuhteeton, Herran sana tulessa koeteltu. Hän on kaikkien kilpi, jotka häneen turvaavat.',
        32: 'Sillä kuka muu on Jumala paitsi Herra, ja kuka muu on pelastuksen kallio paitsi Jumalamme?',
        33: 'Se Jumala, joka on vahva turvani ja johdattaa nuhteetonta hänen tiellään,',
        34: 'tekee hänen jalkansa nopeiksi kuin peurat ja asettaa minut kukkuloilleni,',
        35: 'joka opettaa käteni sotimaan ja käsivarteni vaskijousta jännittämään.',
        36: 'Sinä annat minulle pelastuksen kilven, ja kun kuulet rukoukseni, teet minut suureksi.',
        37: 'Sinä annat askeleilleni avaran tilan, eivätkä jalkani horju.',
        38: 'Minä ajan vihollisiani takaa ja tuhoan heidät enkä palaa, ennen kuin teen heistä lopun.',
        39: 'Lopetan heidät ja murskaan heidät, niin etteivät he enää nouse. He sortuvat jalkojeni alle.',
        40: 'Sinä vyötät minut voimalla sotaan, sinä painat vastustajani alleni.',
        41: 'Sinä ajat viholliseni pakoon, vihamieheni minä hukutan.',
        42: 'He katselevat, mutta pelastajaa ei ole, katsovat Herran puoleen, mutta hän ei heille vastaa.',
        43: 'Survon heidät maan tomuksi, kadun loaksi heidät poljen ja tallaan.',
        44: 'Sinä pelastat minut kansani riidoista, sinä varjelet minua, niin että tulen pakanoiden pääksi. Kansa, jota en tuntenut, palvelee minua.',
        45: 'Muukalaiset minua mielistelevät, jo korvan kuulemalta he tottelevat minua.',
        46: 'Muukalaiset masentuvat. He tulevat vyöttäytyneinä varustuksistaan.',
        47: 'Herra elää! Kiitetty olkoon kallioni, ja ylistetty Jumala, pelastukseni kallio,',
        48: 'Jumala, joka hankkii minulle koston ja laskee kansat valtani alle,',
        49: 'sinä, joka vapahdat minut vihollisistani ja korotat minut vastustajieni yläpuolelle ja päästät minut väkivaltaisesta miehestä.',
        50: 'Sen tähden ylistän sinua, Herra, kansojen keskuudessa ja veisaan nimesi kiitosta,',
        51: 'sinun, joka annat kuninkaallesi suuren avun ja osoitat armoa voidellullesi, Daavidille, ja hänen jälkeläisilleen, iankaikkisesti."',
    },
    23: {
        1: 'Nämä olivat Daavidin viimeiset sanat: Näin puhuu Daavid, Iisain poika, näin puhuu korkealle korotettu mies, Jaakobin Jumalan voideltu, ihana Israelin ylistysvirsissä:',
        2: '" Herran Henki on puhunut minulle, ja hänen sanansa on kielelläni.',
        3: "Israelin Jumala on sanonut, Israelin kallio on puhunut minulle: 'Joka hallitsee ihmisiä vanhurskaudella, joka hallitsee jumalanpelolla,",
        4: "hän on kuin huomenhohde auringon noustessa pilvettömänä aamuna, kun maa kirkkaassa valossa vihannoi sateen jälkeen.'",
        5: 'Eikö sukuni ole näin Jumalan edessä? Sillä hän on tehnyt kanssani iankaikkisen liiton, kaikin puolin taatun ja vakaan. Hän antaa versoa minulle kaiken autuuden ja kaiken ilon.',
        6: 'Mutta kaikki kelvottomat ovat kuin pois heitetyt orjantappurat, joihin ei käsin tartuta.',
        7: 'Jos jonkun on koskettava niihin, hän varustautuu raudalla ja keihäänvarrella. Sitten ne tulella poltetaan, siinä missä ovat."',
        8: 'Nämä ovat Daavidin sankarien nimet: Jooseb-Bassebet, tahkemonilainen, vaunusoturien päällikkö, hän, joka oli heiluttanut keihästään kahdeksansadan kaatuneen yli yhdellä kertaa.',
        9: 'Hänen jälkeensä Eleasar, Doodin poika, joka oli erään aholilaisen poika. Hän oli yksi niistä kolmesta valiosotilaasta, jotka olivat Daavidin kanssa silloin, kun he saattoivat häpeään filistealaiset, jotka olivat kokoontuneet sinne sotimaan. Israelin miehet vetäytyivät silloin takaisin,',
        10: 'mutta hän jäi paikalleen ja surmasi filistealaisia, kunnes hänen kätensä uupui niin, että se kouristui kiinni miekkaan. Herra antoi suuren voiton sinä päivänä. Väki kääntyi vain hänen jälkeensä ryöstämään.',
        11: 'Hänen jälkeensä oli Samma, Aagen poika, hararilainen. Kerran olivat filistealaiset kokoontuneet yhteen joukkoon, ja siellä oli peltopalsta, kokonaan hernettä kasvamassa. Väki pakeni filistealaisia,',
        12: 'mutta hän asettui keskelle palstaa, sai sen pelastetuksi ja voitti filistealaiset, ja niin Herra antoi suuren voiton.',
        13: 'Kerran lähti kolme niistä kolmestakymmenestä päälliköstä liikkeelle, ja he tulivat elonleikkuun aikana Daavidin luo Adullamin luolalle. Filistealaisten joukko oli leiriytynyt Refaimin tasangolle.',
        14: 'Daavid oli silloin Vuorilinnassa, ja filistealaisten vartiosto oli Beetlehemissä.',
        15: 'Daavidin rupesi tekemään mieli vettä, ja hän sanoi: "Jospa joku toisi minulle vettä juodakseni Beetlehemin kaivosta, joka on portin edustalla!"',
        16: 'Silloin murtautuivat ne kolme sankaria filistealaisten leirin läpi ja ammensivat vettä Beetlehemin kaivosta portin edustalta, kantoivat ja toivat sen Daavidille. Mutta hän ei tahtonut sitä juoda, vaan vuodatti sen juomauhriksi Herralle',
        17: 'ja sanoi: "Pois se! Herra varjelkoon minut sitä tekemästä. Onhan se niiden miesten veri, jotka menivät sinne oman henkensä uhalla." Eikä hän tahtonut juoda sitä. Tämän tekivät ne kolme sankaria.',
        18: 'Abisai, Jooabin veli, Serujan poika, oli niiden kolmen päällikkö. Hän oli heiluttanut keihästään kolmensadan kaatuneen yli. Hän oli kuuluisa niiden kolmen joukossa.',
        19: 'Hän oli arvossa pidetty niiden kolmen joukossa ja oli heidän päämiehensä, mutta hän ei vetänyt vertoja niille kolmelle.',
        20: 'Benaja, Joojadan poika, joka oli urhoollisen ja suurista teoistaan kuuluisan miehen poika, oli kotoisin Kabseelista. Hän surmasi kaksi mooabilaista sankaria, laskeutui alas ja tappoi lumituiskun aikana leijonan kaivoon.',
        21: 'Myös hän surmasi egyptiläisen miehen, sen kauhean miehen. Egyptiläisellä oli keihäs kädessä, mutta hän meni häntä vastaan ainoastaan sauva kädessä. Hän tempasi keihään egyptiläisen kädestä ja tappoi hänet hänen omalla keihäällään.',
        22: 'Tällaisia teki Benaja, Joojadan poika. Hän oli kuuluisa niiden kolmen sankarin joukossa.',
        23: 'Hän oli arvossa pidetty niiden kolmenkymmenen joukossa, mutta hän ei vetänyt vertoja niille kolmelle. Daavid asetti hänet henkivartiostonsa päälliköksi.',
        24: 'Niiden kolmenkymmenen joukossa oli Asael, Jooabin veli; Elhanan, Doodon poika, Beetlehemistä;',
        25: 'harodilainen Samma; harodilainen Elika;',
        26: 'pleettiläinen Heles; tekoalainen Iira, Ikkeksen poika;',
        27: 'anatotilainen Abieser; huusalainen Mebunnai;',
        28: 'ahohilainen Salmon; netofalainen Maharai;',
        29: 'netofalainen Heeleb, Baanan poika; Ittai, Riibain poika, benjaminilaisten Gibeasta;',
        30: 'piratonilainen Benaja; Hiddai Nahale-Gaasista;',
        31: 'arabilainen Abi-Albon; barhumilainen Asmavet;',
        32: 'saalbonilainen Eljahba; Bene-Jaasen; Joonatan;',
        33: 'hararilainen Samma; ararilainen Ahiam, Sararin poika;',
        34: 'Elifelet, Ahasbain poika, joka oli erään maakatilaisen poika; giilolainen Eliam, Ahitofelin poika;',
        35: 'karmelilainen Hesrai; arabilainen Paarai;',
        36: 'Jigal, Naatanin poika, Soobasta; gaadilainen Vaani;',
        37: 'ammonilainen Selek; beerotilainen Naharai, Jooabin, Serujan pojan, aseenkantaja;',
        38: 'jeteriläinen Iira; jeteriläinen Gaareb;',
        39: 'heettiläinen Uuria. Kaikkiaan kolmekymmentä seitsemän.',
    },
    24: {
        1: 'Herran viha syttyi taas Israelia kohtaan, niin että hän yllytti Daavidin heitä vastaan, sanoen: "Mene ja laske Israel ja Juuda."',
        2: 'Niin kuningas sanoi Jooabille, sotajoukon päällikölle, joka oli hänen luonaan: "Kiertele kaikki Israelin sukukunnat Daanista Beersebaan asti, ja pitäkää kansan katselmus, että saisin tietää kansan lukumäärän."',
        3: 'Jooab vastasi kuninkaalle: " Herra, Jumalasi, lisätköön kansan, olkoon se kuinka suuri tahansa, satakertaiseksi, ja saakoon herrani, kuningas, nähdä sen omin silmin. Mutta miksi herrani, kuningas, haluaa sellaista?"',
        4: 'Kuitenkin kuninkaan sana velvoitti Jooabia ja sotapäälliköitä. Niin Jooab ja sotapäälliköt lähtivät kuninkaan luota pitämään Israelin kansan katselmusta.',
        5: 'He menivät Jordanin yli ja leiriytyivät Aroeriin, oikealle puolelle jokilaakson keskikohdalla olevaa kaupunkia, Gaadiin ja Jaeseriin päin.',
        6: 'He tulivat Gileadiin ja Tahtim-Hodsin maahan. Sitten he tulivat Daan-Jaaniin ja sieltä ympäri Siidoniin.',
        7: 'He tulivat Tyyron linnoitukseen ja kaikkiin hivviläisten ja kanaanilaisten kaupunkeihin ja menivät sieltä Juudan Etelämaahan Beersebaan asti.',
        8: 'Kun he olivat kierrelleet koko maan, he tulivat yhdeksän kuukauden ja kahdenkymmenen päivän kuluttua takaisin Jerusalemiin.',
        9: 'Jooab ilmoitti kuninkaalle kansan lasketun lukumäärän: Israelissa oli kahdeksansataa tuhatta sotakuntoista miekkamiestä, ja Juudassa oli viisisataa tuhatta miestä.',
        10: 'Mutta Daavidin sydän soimasi häntä, sitten kun hän oli laskenut kansan, ja Daavid sanoi Herralle: "Olen tehnyt suuren synnin tehdessäni tämän. Mutta, Herra, anna nyt anteeksi palvelijasi rikos, sillä olen menetellyt hyvin tyhmästi."',
        11: 'Kun Daavid nousi aamulla, profeetta Gaadille, Daavidin näkijälle, oli tullut tämä Herran sana:',
        12: '"Mene ja puhu Daavidille: Näin sanoo Herra: Kolme vaihtoehtoa minä asetan eteesi. Valitse niistä yksi, niin teen sen sinulle."',
        13: 'Gaad meni Daavidin luo, ilmoitti ja sanoi hänelle: "Tuleeko nälkä seitsemäksi vuodeksi maahasi, vai pakenetko sinä kolme kuukautta vihollisiasi, jotka ajavat sinua takaa, vai tuleeko rutto maahasi kolmeksi päiväksi? Mieti nyt ja katso, mitä vastaan hänelle, joka minut lähetti."',
        14: 'Daavid vastasi Gaadille: "Olen suuressa hädässä. Tahdomme langeta Herran käsiin, sillä hänen laupeutensa on suuri. Ihmisten käsiin en tahdo langeta."',
        15: 'Herra antoi ruton tulla Israeliin, aamusta alkaen määrättyyn aikaan asti. Kansaa kuoli Daanista Beersebaan asti seitsemänkymmentä tuhatta miestä.',
        16: 'Mutta kun enkeli ojensi kätensä Jerusalemia kohti tuhotakseen sen, Herra katui sitä pahaa ja sanoi enkelille, joka tuhosi kansaa: "Jo riittää. Laske kätesi alas." Herran enkeli oli silloin jebusilaisen Araunan puimatantereen luona.',
        17: 'Mutta nähdessään enkelin surmaavan kansaa Daavid sanoi Herralle: "Katso, minä olen tehnyt syntiä, minä olen tehnyt väärin. Mutta mitä nämä lampaani ovat tehneet? Sattukoon kätesi minuun ja isäni perheeseen."',
        18: 'Gaad tuli Daavidin luo samana päivänä ja sanoi hänelle: "Mene ja pystytä Herralle alttari jebusilaisen Araunan puimatantereelle."',
        19: 'Daavid meni, Gaadin sanan ja Herran käskyn mukaan.',
        20: 'Mutta kun Arauna katsoi ulos ja näki kuninkaan palvelijoineen tulevan luokseen, hän meni ulos ja kumartui kasvoilleen maahan kuninkaan eteen.',
        21: 'Arauna sanoi: "Miksi herrani kuningas tulee palvelijansa luo?" Daavid vastasi: "Ostamaan sinulta puimatantereen rakentaakseni Herralle alttarin, että vitsaus väistyisi kansasta."',
        22: 'Arauna sanoi Daavidille: "Herrani kuningas ottakoon ja uhratkoon, mitä hyväksi näkee. Katso, tässä on härät polttouhriksi ja puimaäkeet sekä härkien kalustoa polttopuiksi.',
        23: 'Tämän kaiken, kuningas, Arauna antaa kuninkaalle." Arauna sanoi kuninkaalle: "Olkoon Herra, Jumalasi, sinulle suosiollinen."',
        24: 'Mutta kuningas sanoi Araunalle: "Ei niin, vaan ostan ne sinulta täydestä hinnasta, sillä en uhraa Herralleni, Jumalalleni, ilmaiseksi saatuja polttouhreja." Daavid osti puimatantereen ja härät viidelläkymmenellä hopeasekelillä.',
        25: 'Daavid rakensi sinne alttarin Herralle ja uhrasi polttouhreja ja rauhanuhreja. Herra armahti maata, ja vitsaus taukosi Israelista.',
    },
}
